script:
flt = frappe.utils.flt
op = frappe.form_dict.get("op")
opp = frappe.form_dict.get("name")
o = frappe.get_doc("Opportunity", opp)
if op == "info":
    cost = {}
    label = {}
    for c in o.custom_costing:
        k = c.get("pricing_request")
        if k:
            cost[k] = cost.get(k, 0) + flt(c.get("cost"))
            if k not in label:
                label[k] = c.get("custom_item") or c.get("description") or k
    rows = []
    for p in frappe.get_all("Pricing Request", filters={"opportunity": opp, "docstatus": ["<", 2]}, fields=["name", "status"], order_by="creation"):
        rows.append({"pr": p.name, "status": p.status, "label": label.get(p.name, p.name), "cost": cost.get(p.name, 0)})
    frappe.response["message"] = {"rows": rows, "currency": o.get("currency")}
elif op == "send":
    prs = json.loads(frappe.form_dict.get("prs") or "[]")
    note = (frappe.form_dict.get("note") or "").strip()
    need = frappe.form_dict.get("needed_by") or None
    if not prs:
        frappe.throw("Pick at least one Cost Sheet")
    if not note:
        frappe.throw("Write what should change")
    done = []
    for p in prs:
        if frappe.db.get_value("Pricing Request", p, "opportunity") != opp:
            continue
        frappe.db.set_value("Pricing Request", p, {"status": "With Production", "custom_revision_from_sales": 1,
            "custom_revision_note": note, "custom_revision_needed_by": need})
        frappe.get_doc("Pricing Request", p).add_comment("Comment", "Sales asked a revision: " + note)
        done.append(p)
    if done:
        frappe.db.set_value("Opportunity", opp, "custom_pricing_status", "With Production")
        o.add_comment("Comment", "Asked Production to revise " + ", ".join(done) + ": " + note)
    frappe.response["message"] = {"ok": 1, "done": done}

if doc.has_value_changed("sales_stage") and doc.sales_stage == "Proposal":
    exists = frappe.get_all("Proposal", filters={"opportunity": doc.name, "docstatus": ["<", 2]}, limit=1)
    if not exists:
        frappe.call("eye.proposal", action="make", opportunity=doc.name, mode="full")

names = json.loads(frappe.form_dict.get("names") or "[]")
flt = frappe.utils.flt
today = frappe.utils.getdate(frappe.utils.today())
FINAL = ['Priced']
CH = "Opportunity Costing"
WON = ["Deals in Hand", "Finance, please approve", "Quote approved"]

def age(dt):
    if not dt:
        return ""
    n = frappe.utils.date_diff(today, frappe.utils.getdate(dt))
    if n <= 0:
        return "today"
    return str(n) + " d"

out = {}
for n in names[:300]:
    o = frappe.db.get_value("Opportunity", n, ["name", "sales_stage", "custom_po_no", "custom_expected_po_date", "custom_accounts_approval", "modified", "custom_pl", "custom_pl_outdated", "custom_deal_name"], as_dict=True)
    if not o:
        continue
    stage = o.sales_stage or ""
    items = []
    for c in frappe.get_all("Pricing Change", filters={"opportunity": n, "status": ["in", ["Requested", "Pending"]]}, fields=["name", "creation"]):
        items.append({"tone": "orange", "who": "Sales", "label": "Your action", "text": "Approve the price change", "sub": "Production changed the cost · " + c.name, "btn": "Review change", "route": ["Form", "Pricing Change", c.name], "age": age(c.creation)})
    for p in frappe.get_all("Pricing Request", filters={"opportunity": n}, fields=["name", "status", "creation", "modified", "custom_revision_from_sales"]):
        st = p.status or ""
        if st == "Change Requested":
            items.insert(0, {"tone": "orange", "who": "Sales", "label": "Your action", "text": "Production asked a price change", "sub": p.name, "btn": "Review change", "route": ["Form", "Pricing Request", p.name], "age": age(p.modified)})
        elif st == "Returned to Sales":
            items.insert(0, {"tone": "orange", "who": "Sales", "label": "Your action", "text": "Production has a question", "sub": p.name, "btn": "Answer", "route": ["Form", "Pricing Request", p.name], "age": age(p.modified)})
        elif st not in FINAL:
            items.append({"tone": "amber", "who": "Production", "label": "Waiting on Production", "text": ("Revising Cost Sheet (asked by Sales)" if p.get("custom_revision_from_sales") else "Cost Sheet not ready"), "sub": p.name + " · " + st, "btn": "Open request", "route": ["Form", "Pricing Request", p.name], "age": age(p.creation)})
    if stage and stage != "Estimation":
        bad = 0
        for r in frappe.get_all(CH, filters={"parent": n, "parenttype": "Opportunity"}, fields=["cost", "margin", "selling"]):
            if flt(r.selling) <= 0 or (flt(r.cost) > 0 and flt(r.margin) <= 0):
                bad = bad + 1
        if bad:
            items.append({"tone": "orange", "who": "Sales", "label": "Your action", "text": str(bad) + " P&L line(s) without price", "sub": "Set the margin or the selling price", "btn": "Edit P&L", "action": "pl", "age": ""})
    if o.custom_pl:
        if o.custom_pl_outdated:
            items.append({"tone": "orange", "who": "Sales", "label": "Your action", "text": "P&L is outdated", "sub": "Costs changed after " + o.custom_pl, "btn": "Update P&L", "action": "pl_rev", "age": ""})
        qq = frappe.get_all("Quotation", filters={"opportunity": n, "docstatus": ["<", 2], "custom_superseded": 0}, fields=["name", "custom_pl"], order_by="creation desc", limit=1)
        if qq and qq[0].custom_pl and qq[0].custom_pl != o.custom_pl:
            items.append({"tone": "orange", "who": "Sales", "label": "Your action", "text": "Quotation is on an old P&L", "sub": qq[0].name + " · " + qq[0].custom_pl, "btn": "Update Quotation", "action": "uq", "age": ""})
    po = None
    if o.custom_po_no:
        po = {"text": "received · " + o.custom_po_no, "tag": "Received", "tone": "green"}
    elif o.custom_expected_po_date:
        dd = frappe.utils.date_diff(frappe.utils.getdate(o.custom_expected_po_date), today)
        ds = frappe.utils.formatdate(o.custom_expected_po_date, "dd MMM")
        if dd < 0:
            po = {"text": "expected " + ds, "tag": "Overdue", "tone": "red"}
            if stage in WON:
                items.append({"tone": "orange", "who": "Customer", "label": "Waiting on Customer", "text": "Purchase Order", "sub": "expected " + ds, "btn": "Open deal", "route": ["Form", "Opportunity", n], "age": str(0 - dd) + " d late"})
        elif dd == 0:
            po = {"text": "expected " + ds, "tag": "Due today", "tone": "amber"}
        else:
            po = {"text": "expected " + ds, "tag": "Not due", "tone": "gray"}
    out[n] = {"deal": o.custom_deal_name, "box": items[0] if items else None, "more": items[1:], "po": po}
frappe.response["message"] = out

if doc.has_value_changed("custom_deal_name"):
    for n in frappe.get_all("Pricing Request", filters={"opportunity": doc.name}, pluck="name"):
        frappe.db.set_value("Pricing Request", n, "custom_deal_name", doc.custom_deal_name, update_modified=False)

doc.custom_deal_name = " ".join((doc.custom_deal_name or "").split())
if doc.custom_deal_name:
    other = frappe.db.get_value("Opportunity", {"custom_deal_name": doc.custom_deal_name, "name": ["!=", doc.name or ""]}, ["name", "customer_name"], as_dict=True)
    if other:
        frappe.throw("The deal name " + doc.custom_deal_name + " is already used by " + other.name + " (" + (other.customer_name or "") + "). Choose another name.", title="Deal name already used")

keep = {}
for r in doc.get("custom_proposal_items") or []:
    if r.opportunity_item:
        keep[r.opportunity_item] = r
rows = []
total = 0
for it in doc.get("items") or []:
    if not (frappe.utils.flt(it.amount) or frappe.utils.flt(it.rate)):
        continue
    key = it.name or ((it.item_code or "") + "-" + str(it.idx))
    old = keep.get(key)
    hide = 1 if (old and old.hide_in_proposal) else 0
    rows.append({"opportunity_item": key, "item_code": it.item_code, "item_name": it.item_name,
                 "description": (old.description if old and old.description else (frappe.utils.strip_html(it.description or "").strip() or it.item_name)),
                 "qty": it.qty, "uom": it.uom, "rate": frappe.utils.flt(it.rate, 2), "amount": frappe.utils.flt(it.amount, 2), "hide_in_proposal": hide})
    if not hide:
        total = total + frappe.utils.flt(it.amount)
doc.set("custom_proposal_items", [])
for r in rows:
    doc.append("custom_proposal_items", r)
doc.custom_proposal_total = frappe.utils.flt(total, 2)

a = frappe.form_dict
action = a.get("action") or "info"
opp = frappe.get_doc("Opportunity", a.get("opportunity"))
flt = frappe.utils.flt

cur = {}
order = []
for it in opp.get("items") or []:
    if not it.item_code or not (flt(it.amount) or flt(it.rate)):
        continue
    k = it.item_code
    if k not in cur:
        cur[k] = {"qty": 0, "amount": 0, "item_name": it.item_name}
        order.append(k)
    cur[k]["qty"] = cur[k]["qty"] + flt(it.qty)
    cur[k]["amount"] = cur[k]["amount"] + (flt(it.amount) or flt(it.qty) * flt(it.rate))

quotes = frappe.get_all("Quotation", filters={"opportunity": opp.name, "docstatus": ["<", 2]},
    fields=["name", "docstatus", "status", "grand_total", "currency", "custom_quote_type", "custom_superseded", "transaction_date"],
    order_by="creation desc")
active = [q.name for q in quotes if not q.custom_superseded]

base = {}
if active:
    for r in frappe.get_all("Quotation Item", filters={"parent": ["in", active], "parenttype": "Quotation"}, fields=["item_code", "qty", "amount"]):
        if r.item_code not in base:
            base[r.item_code] = {"qty": 0, "amount": 0}
        base[r.item_code]["qty"] = base[r.item_code]["qty"] + flt(r.qty)
        base[r.item_code]["amount"] = base[r.item_code]["amount"] + flt(r.amount)

full = []
delta = []
reductions = []
for k in order:
    c = cur[k]
    q = c["qty"] or 1
    unit = flt(c["amount"] / q, 2)
    full.append({"item_code": k, "qty": q, "rate": unit, "amount": c["amount"]})
    b = base.get(k) or {"qty": 0, "amount": 0}
    da = c["amount"] - b["amount"]
    dq = c["qty"] - b["qty"]
    if da > 0.005:
        if dq > 0 and abs(da - dq * c["amount"] / q) < 0.01:
            delta.append({"item_code": k, "qty": dq, "rate": unit, "amount": da})
        else:
            delta.append({"item_code": k, "qty": q, "rate": flt(da / q, 2), "amount": da})
    elif da < -0.005:
        reductions.append(c["item_name"] or k)
for k in base:
    if k not in cur and base[k]["amount"] > 0.005:
        reductions.append(frappe.db.get_value("Item", k, "item_name") or k)

priced = [c.requirement for c in (opp.get("custom_costing") or []) if flt(c.selling) > 0]
unpriced = [r.item_code for r in (opp.get("custom_requirements") or []) if r.item_code and r.name not in priced]

lock = ""
so_amend = None
so_name = opp.get("custom_sales_order")
if not so_name and active:
    so_name = frappe.db.get_value("Sales Order Item", {"prevdoc_docname": ["in", active], "docstatus": 1}, "parent")
so_mode = None
if so_name:
    sod = frappe.db.get_value("Sales Order", so_name, ["docstatus", "per_billed", "per_delivered"], as_dict=True)
    if sod and sod.docstatus == 1:
        so_amend = so_name
        so_mode = "amend"
        if flt(sod.per_billed) > 0 or flt(sod.per_delivered) > 0 or flt(opp.get("custom_invoiced_pct")) > 0 or frappe.db.exists("Billing Request", {"sales_order": so_name, "docstatus": ["<", 2]}):
            so_mode = "update"

if action == "info":
    frappe.response["message"] = {
        "quotes": quotes, "active": active, "currency": opp.currency, "lock": lock, "so_amend": so_amend, "so_mode": so_mode, "unpriced": unpriced, "reductions": reductions,
        "full_count": len(full), "full_total": sum([l["amount"] for l in full]),
        "delta_count": len(delta), "delta_total": sum([l["amount"] for l in delta]),
    }
elif action == "make":
    mode = a.get("mode") or "full"
    if unpriced:
        frappe.throw("Set a selling price in the P&L for: " + ", ".join(unpriced))
    if not active:
        frappe.throw("There is no quotation yet: use Create Quotation")
    if mode == "full" and lock:
        frappe.throw("A new full quotation can't replace the current one: " + lock + ". Use Only the changes.")
    lines = full if mode == "full" else delta
    if not lines:
        frappe.throw("Nothing was added or increased since the current quotation." if mode != "full" else "The deal has no priced items.")
    if mode == "full" and sum([l["amount"] for l in full]) + 0.005 < flt(opp.get("custom_total_selling")):
        frappe.throw("Items total is below the minimum selling total " + frappe.utils.fmt_money(opp.custom_total_selling, currency=opp.currency))
    if mode == "full" and so_mode == "amend":
        oso = frappe.get_doc("Sales Order", so_amend)
        oso.flags.ignore_permissions = True
        oso.flags.ignore_links = True
        oso.cancel()
    new = frappe.call("erpnext.crm.doctype.opportunity.opportunity.make_quotation", source_name=opp.name)
    tmpl = {}
    for i in new.items:
        if i.item_code not in tmpl:
            row = i.as_dict()
            for f in ["name", "parent", "parenttype", "parentfield", "idx", "creation", "modified", "owner", "modified_by",
                      "docstatus", "doctype", "price_list_rate", "discount_percentage", "discount_amount", "base_rate",
                      "base_amount", "net_rate", "net_amount", "base_net_rate", "base_net_amount"]:
                row.pop(f, None)
            tmpl[i.item_code] = row
    new.set("items", [])
    for l in lines:
        row = dict(tmpl.get(l["item_code"]) or {"item_code": l["item_code"]})
        row["qty"] = l["qty"]
        row["rate"] = l["rate"]
        row["amount"] = flt(l["qty"] * l["rate"], 2)
        row["stock_qty"] = l["qty"] * flt(row.get("conversion_factor") or 1)
        new.append("items", row)
    new.custom_quote_type = "Full" if mode == "full" else "Changes only"
    new.custom_revision_of = active[0]
    new.custom_superseded = 0
    if not new.valid_till:
        new.valid_till = frappe.utils.add_days(frappe.utils.nowdate(), 30)
    new.flags.ignore_permissions = True
    new.insert()
    if mode == "full":
        for n in active:
            old = frappe.get_doc("Quotation", n)
            if old.docstatus == 1 and so_mode != "update":
                old.flags.ignore_permissions = True
                old.cancel()
            frappe.db.set_value("Quotation", n, "custom_superseded", 1)
    if mode == "full" and so_mode == "update":
        new.reload()
        new.flags.ignore_permissions = True
        new.submit()
        sodoc = frappe.get_doc("Sales Order", so_amend)
        first = {}
        for r in sodoc.items:
            if r.item_code not in first:
                first[r.item_code] = r
        trans = []
        for l in full:
            r = first.get(l["item_code"])
            if r:
                trans.append({"docname": r.name, "item_code": l["item_code"], "qty": l["qty"], "rate": l["rate"],
                    "conversion_factor": r.conversion_factor or 1, "uom": r.uom, "delivery_date": str(r.delivery_date or sodoc.delivery_date)})
            else:
                trans.append({"item_code": l["item_code"], "qty": l["qty"], "rate": l["rate"], "conversion_factor": 1,
                    "uom": frappe.db.get_value("Item", l["item_code"], "stock_uom"), "delivery_date": str(sodoc.delivery_date)})
        frappe.call("erpnext.controllers.accounts_controller.update_child_qty_rate", parent_doctype="Sales Order",
            trans_items=json.dumps(trans), parent_doctype_name=so_amend, child_docname="items")
        opp.add_comment("Info", "Sales Order " + so_amend + " updated to the new full quotation " + new.name)
        frappe.msgprint("Sales Order " + so_amend + " was updated with the new prices (invoices already made stay as they are).")
    if mode == "full" and so_mode == "amend":
        new.reload()
        new.flags.ignore_permissions = True
        new.submit()
        so = frappe.call("erpnext.selling.doctype.quotation.quotation.make_sales_order", source_name=new.name)
        oldso = frappe.get_doc("Sales Order", so_amend)
        so.amended_from = so_amend
        for f in ["delivery_date", "po_no", "po_date"]:
            if oldso.get(f):
                so.set(f, oldso.get(f))
        for it in so.items:
            if not it.delivery_date:
                it.delivery_date = so.delivery_date
        so.flags.ignore_permissions = True
        so.insert()
        so.submit()
        frappe.db.set_value("Opportunity", opp.name, "custom_sales_order", so.name)
        opp.add_comment("Info", "Sales Order " + so_amend + " replaced by " + so.name + " (new full quotation " + new.name + ")")
        frappe.msgprint("Sales Order " + so_amend + " was replaced by " + so.name + " with the new prices.")
    frappe.response["message"] = new.name

# every service (no Production needed) gets a P&L line: cost 0, margin 100%, sales enter the selling price
eye_reqs = [r for r in (doc.get("custom_requirements") or []) if r.item_code]
eye_req_names = [r.name for r in eye_reqs]
doc.set("custom_costing", [c for c in (doc.get("custom_costing") or []) if c.requirement in eye_req_names or c.pricing_request])
eye_have = [c.requirement for c in (doc.get("custom_costing") or [])]
for eye_r in eye_reqs:
    if eye_r.name and eye_r.name not in eye_have and frappe.db.get_value("Item", eye_r.item_code, "item_group") == "Service":
        doc.append("custom_costing", {"requirement": eye_r.name, "description": eye_r.description or eye_r.item_code,
                                      "qty": eye_r.qty or 1, "cost": 0, "margin": 100, "selling": 0})

# every P&L line shows its item and type, from the Services
eye_by_req = {}
for r in doc.get("custom_requirements") or []:
    eye_by_req[r.name] = r
for c in doc.get("custom_costing") or []:
    r = eye_by_req.get(c.requirement)
    if r:
        c.custom_item = r.item_code
        c.custom_item_group = r.get("custom_item_group") or frappe.db.get_value("Item", r.item_code, "item_group")

flt = frappe.utils.flt
total = 0
for r in doc.get("items") or []:
    if flt(r.qty) and flt(r.rate):
        r.amount = flt(flt(r.qty) * flt(r.rate), 2)
    if not r.hide_in_proposal:
        total += flt(r.amount)
doc.total = flt(total, 2)
if doc.taxes_and_charges:
    rate = 0
    for t in frappe.get_all("Sales Taxes and Charges", filters={"parent": doc.taxes_and_charges, "parenttype": "Sales Taxes and Charges Template"}, fields=["rate", "charge_type"]):
        if t.charge_type == "On Net Total":
            rate += flt(t.rate)
    doc.tax_rate = rate
if not doc.tax_label or doc.tax_label.endswith("% VAT"):
    doc.tax_label = (("%g" % flt(doc.tax_rate)) + "% VAT") if flt(doc.tax_rate) else ""
doc.tax_amount = flt(total * flt(doc.tax_rate) / 100, 2)
doc.grand_total = flt(total + doc.tax_amount, 2)
if doc.terms_template and not doc.terms:
    doc.terms = frappe.db.get_value("Terms and Conditions", doc.terms_template, "terms")
if doc.prepared_by:
    doc.prepared_by_name = frappe.db.get_value("User", doc.prepared_by, "full_name")
if not doc.get("items"):
    frappe.throw("Add at least one line to the proposal.")

a = frappe.form_dict
action = a.get("action") or "info"
opp = frappe.get_doc("Opportunity", a.get("opportunity"))
flt = frappe.utils.flt

cur = {}
order = []
for it in ([r for r in (opp.get("custom_proposal_items") or []) if not r.hide_in_proposal] or opp.get("items") or []):
    if not it.item_code or not (flt(it.amount) or flt(it.rate)):
        continue
    k = it.item_code
    if k not in cur:
        cur[k] = {"item_code": k, "item_name": it.item_name, "uom": it.uom, "qty": 0, "amount": 0,
                  "description": frappe.utils.strip_html(it.description or "").strip() or it.item_name or k}
        order.append(k)
    cur[k]["qty"] = cur[k]["qty"] + (flt(it.qty))
    cur[k]["amount"] = cur[k]["amount"] + (flt(it.amount) or flt(it.qty) * flt(it.rate))

proposals = frappe.get_all("Proposal", filters={"opportunity": opp.name},
    fields=["name", "proposal_date", "proposal_type", "status", "total", "grand_total", "currency", "revision_of"],
    order_by="creation desc")
active = [p.name for p in proposals if p.status not in ("Superseded", "Rejected")]

base = {}
for p in active:
    for r in frappe.get_all("Eye Proposal Item", filters={"parent": p, "parenttype": "Proposal"}, fields=["item_code", "qty", "amount"]):
        if r.item_code not in base:
            base[r.item_code] = {"qty": 0, "amount": 0}
        base[r.item_code]["qty"] = base[r.item_code]["qty"] + (flt(r.qty))
        base[r.item_code]["amount"] = base[r.item_code]["amount"] + (flt(r.amount))

full_lines = []
delta_lines = []
reductions = []
for k in order:
    c = cur[k]
    q = c["qty"] or 1
    unit = c["amount"] / q
    full_lines.append({"item_code": k, "item_name": c["item_name"], "description": c["description"], "uom": c["uom"],
                       "qty": q, "rate": flt(unit, 2), "amount": c["amount"]})
    b = base.get(k) or {"qty": 0, "amount": 0}
    da = c["amount"] - b["amount"]
    dq = c["qty"] - b["qty"]
    if da > 0.005:
        if dq > 0 and abs(da - dq * unit) < 0.01:
            dqty = dq
            drate = flt(unit, 2)
        else:
            dqty = q
            drate = flt(da / q, 2)
        delta_lines.append({"item_code": k, "item_name": c["item_name"], "description": c["description"], "uom": c["uom"],
                            "qty": dqty, "rate": drate, "amount": da})
    elif da < -0.005:
        reductions.append(c["item_name"] or k)
for k in base:
    if k not in cur and base[k]["amount"] > 0.005:
        reductions.append(frappe.db.get_value("Item", k, "item_name") or k)

eye_priced = [c.requirement for c in (opp.get("custom_costing") or []) if flt(c.selling) > 0]
unpriced = [r.item_code for r in (opp.get("custom_requirements") or []) if r.item_code and r.name not in eye_priced]

if action == "info":
