# Eye CRM accounting adapter: the deal and billing cycle lives in ERPNext, and this script
# carries it to the accounting system. The mode is in Eye Books Settings:
#
#   Manual  nothing is sent; Accounts approve and Finance records invoices with buttons.
#   Zoho    quotes go to Zoho Books as Estimates, invoice requests as Sales Orders; approvals,
#           invoices and payments come back from Zoho (a 5-minute job, nudged by a webhook).
#
#   desk:     frappe.call({method: "eye.books", args: {op: "test"}}) -> r.message.result
#   scripts:  frappe.call("eye.books", op="send_quote", name=opportunity)
#
# Every call to Zoho is written to Eye Sync Log; a failed one can be retried from there.

ACCOUNTS_STAGE = "Finance, please approve"
