# ---------------------------------------------------------------- helpers

def fmt(msg, values):
    out = _(msg)
    for i, v in enumerate(values):
        out = out.replace("{" + str(i) + "}", str(v))
    return out


def text(v):
    return " ".join(str(v or "").split())


def has_role(role):
    user = frappe.session.user
    if user == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {"parent": user, "parenttype": "User", "role": role}))


def require_manager():
    if not (has_role("System Manager") or has_role("Accounts Manager")):
        frappe.throw(_("Only an Accounts Manager can do this"))


def settings():
    return frappe.get_doc(SETTINGS, SETTINGS)


def mode():
    return frappe.db.get_single_value(SETTINGS, "mode") or "Manual"


def log(operation, doctype, name, ok, request=None, response=None, error=None):
    frappe.get_doc({"doctype": "Eye Sync Log", "operation": operation, "reference_doctype": doctype,
                    "reference_name": name, "status": "Success" if ok else "Error",
                    "request": json.dumps(request, indent=1, default=str) if request else None,
                    "response": json.dumps(response, indent=1, default=str)[:20000] if response else None,
                    "error": text(error)[:1000] if error else None}).insert(ignore_permissions=True)


# ---------------------------------------------------------------- Zoho Books

def token():
    s = settings()
    if s.access_token and s.token_expires and str(s.token_expires) > str(frappe.utils.add_to_date(frappe.utils.now_datetime(), minutes=2)):
        return s.get_password("access_token")
    accounts = (s.accounts_domain or "https://accounts.zoho.com").rstrip("/")
    out = frappe.make_post_request(accounts + "/oauth/v2/token", params={
        "refresh_token": s.get_password("refresh_token"), "client_id": s.client_id,
        "client_secret": s.get_password("client_secret"), "grant_type": "refresh_token"})
    if not out or not out.get("access_token"):
        frappe.throw(fmt("Zoho didn't give an access token: {0}", [text((out or {}).get("error") or out)]))
    s = settings()
    s.access_token = out.get("access_token")
    s.token_expires = frappe.utils.add_to_date(frappe.utils.now_datetime(), seconds=int(out.get("expires_in") or 3600))
    s.flags.ignore_permissions = True
    s.flags.ignore_mandatory = True
    s.save()
    return out.get("access_token")


def zoho_error(e):
    # the HTTP status and URL (no token: it travels in a header); Zoho's full answer is in the Error Log
    return text(str(e))[:500]


def zoho(method, path, params=None, body=None):
    s = settings()
    url = (s.api_domain or "https://www.zohoapis.com").rstrip("/") + "/books/v3" + path
    query = {"organization_id": s.organization_id}
    query.update(params or {})
    headers = {"Authorization": "Zoho-oauthtoken " + token(), "Content-Type": "application/json"}
    try:
        if method == "GET":
            out = frappe.make_get_request(url, params=query, headers=headers)
        elif method == "PUT":
            out = frappe.make_put_request(url, params=query, headers=headers, json=body)
        else:
            out = frappe.make_post_request(url, params=query, headers=headers, json=body)
    except Exception as e:
        frappe.throw(zoho_error(e), title=_("Zoho Books"))
    if isinstance(out, dict) and out.get("code") not in (None, 0):
        frappe.throw(str(out.get("code")) + ": " + text(out.get("message")), title=_("Zoho Books"))
    return out or {}


def custom_fields(pairs):
    return [{"api_name": k, "value": v} for k, v in pairs if k and v]


def zoho_customer(customer):
    """The customer's Zoho contact id; a customer made in ERPNext is created in Zoho once."""
    c = frappe.get_doc("Customer", customer)
    if c.custom_zoho_contact_id:
        return c.custom_zoho_contact_id
    out = zoho("POST", "/contacts", body={"contact_name": c.customer_name, "company_name": c.customer_name,
                                           "contact_type": "customer"})
    contact_id = out.get("contact", {}).get("contact_id")
    frappe.db.set_value("Customer", customer, "custom_zoho_contact_id", contact_id, update_modified=False)
    log("Create customer", "Customer", customer, True, {"contact_name": c.customer_name}, out.get("contact"))
    return contact_id


def zoho_lines(rows):
    out = []
    for r in rows:
        item_id = frappe.db.get_value("Item", r.item_code, "custom_zoho_item_id")
        if not item_id:
            frappe.throw(fmt("Item {0} isn't linked to Zoho Books: sync the items from Zoho, then try again", [r.item_code]))
        out.append({"item_id": item_id, "description": text(frappe.utils.strip_html(r.description or ""))[:2000],
                    "quantity": flt(r.qty), "rate": flt(r.rate)})
    return out


# ---------------------------------------------------------------- quote -> Estimate (approval)

def send_quote(name):
    """The deal entered "Finance, please approve": its quote goes to the accounting system."""
    if mode() != "Zoho":
        return "manual"
    try:
        return push_estimate(name)
    except Exception as e:
        log("Send quote", "Opportunity", name, False, error=str(e))
        frappe.get_doc("Opportunity", name).add_comment(
            "Comment", fmt("The quote didn't reach Zoho Books: {0}. Retry it from Eye Sync Log.", [text(str(e))[:300]]))
        return "error"


def push_estimate(name):
    opp = frappe.get_doc("Opportunity", name)
    rows = frappe.get_all("Quotation", filters={"opportunity": name, "docstatus": ["<", 2]}, pluck="name",
                          order_by="modified desc", limit=1)
    if not rows:
        frappe.throw(_("The deal has no quotation"))
    q = frappe.get_doc("Quotation", rows[0])
    if q.quotation_to != "Customer":
        frappe.throw(_("The quotation is for a lead: make it a customer first"))
    s = settings()
    body = {"customer_id": zoho_customer(q.party_name), "reference_number": name, "date": str(q.transaction_date),
            "line_items": zoho_lines(q.items),
            "custom_fields": custom_fields([(s.deal_field, name)])}
    out = zoho("POST", "/estimates", body=body)
    est = out.get("estimate") or {}
    zoho("POST", "/estimates/" + est.get("estimate_id") + "/status/sent")
    frappe.db.set_value("Opportunity", name, "custom_zoho_estimate_id", est.get("estimate_id"), update_modified=False)
    opp.add_comment("Info", fmt("Sent to Zoho Books as Estimate {0}", [est.get("estimate_number")]))
    log("Send quote", "Opportunity", name, True, body, est)
    return est.get("estimate_id")


def check_quotes():
    """Deals waiting for Accounts: an accepted Estimate approves, a declined one sends it back."""
    done = 0
    for d in frappe.get_all("Opportunity", filters={"sales_stage": ACCOUNTS_STAGE, "custom_zoho_estimate_id": ["is", "set"]},
                            fields=["name", "custom_zoho_estimate_id"]):
        try:
            est = zoho("GET", "/estimates/" + d.custom_zoho_estimate_id).get("estimate") or {}
            status = est.get("status")
            if status in ("accepted", "invoiced"):
                frappe.call("eye.pricing", op="approve_project", name=d.name, note=_("Approved in Zoho Books"))
                log("Approval", "Opportunity", d.name, True, response={"status": status})
                done = done + 1
            elif status == "declined":
                reason = text(est.get("notes")) or _("Declined in Zoho Books")
                frappe.call("eye.pricing", op="reject_project", name=d.name, reason=reason)
                log("Approval", "Opportunity", d.name, True, response={"status": status})
                done = done + 1
        except Exception as e:
            log("Approval", "Opportunity", d.name, False, error=str(e))
    return done


