def send_invoice_request(name):
    """The request entered "Finance, please issue": it goes to the accounting system."""
    if mode() != "Zoho":
        return "manual"
    try:
        return push_sales_order(name)
    except Exception as e:
        log("Send invoice request", "Billing Request", name, False, error=str(e))
        frappe.get_doc("Billing Request", name).add_comment(
            "Comment", fmt("The request didn't reach Zoho Books: {0}. Retry it from Eye Sync Log.", [text(str(e))[:300]]))
        return "error"


def push_sales_order(name):
    br = frappe.get_doc("Billing Request", name)
    s = settings()
    body = {"customer_id": zoho_customer(br.customer), "reference_number": name, "date": frappe.utils.nowdate(),
            "shipment_date": str(br.expected_date), "line_items": zoho_lines(br.items), "notes": text(br.notes) or None,
            "custom_fields": custom_fields([(s.deal_field, br.opportunity), (s.billing_field, name)])}
    out = zoho("POST", "/salesorders", body=body)
    so = out.get("salesorder") or {}
    zoho("POST", "/salesorders/" + so.get("salesorder_id") + "/status/open")
    frappe.db.set_value("Billing Request", name, "zoho_salesorder_id", so.get("salesorder_id"), update_modified=False)
    br.add_comment("Info", fmt("Sent to Zoho Books as Sales Order {0}", [so.get("salesorder_number")]))
    log("Send invoice request", "Billing Request", name, True, body, so)
    return so.get("salesorder_id")


def check_invoices():
    """Requests with Finance: the invoice made from the Zoho Sales Order, then its payments."""
    done = 0
    for r in frappe.get_all("Billing Request", filters={"billing_stage": TO_FINANCE, "zoho_salesorder_id": ["is", "set"]},
                            fields=["name", "zoho_salesorder_id"]):
        try:
            so = zoho("GET", "/salesorders/" + r.zoho_salesorder_id).get("salesorder") or {}
            invoices = [i for i in so.get("invoices") or [] if i.get("status") not in ("void", "draft")]
            if invoices:
                inv = invoices[0]
                frappe.call("eye.billing", op="mark_invoiced", name=r.name, invoice_number=inv.get("invoice_number"),
                            invoice_date=inv.get("date"), zoho_invoice_id=inv.get("invoice_id"))
                log("Invoice", "Billing Request", r.name, True, response=inv)
                done = done + 1
        except Exception as e:
            log("Invoice", "Billing Request", r.name, False, error=str(e))
    for r in frappe.get_all("Billing Request", filters={"billing_stage": INVOICED, "zoho_invoice_id": ["is", "set"]},
                            fields=["name", "zoho_invoice_id", "collected_amount"]):
        try:
            inv = zoho("GET", "/invoices/" + r.zoho_invoice_id).get("invoice") or {}
            paid = flt(inv.get("total")) - flt(inv.get("balance"))
            when = inv.get("last_payment_date") or frappe.utils.nowdate()
            if inv.get("status") == "paid":
                frappe.call("eye.billing", op="mark_collected", name=r.name, collected_on=when, amount=paid)
                log("Payment", "Billing Request", r.name, True, response={"status": "paid", "paid": paid})
                done = done + 1
            elif paid > flt(r.collected_amount):
                frappe.call("eye.billing", op="record_payment", name=r.name, amount=paid, collected_on=when)
                log("Payment", "Billing Request", r.name, True, response={"status": inv.get("status"), "paid": paid})
        except Exception as e:
            log("Payment", "Billing Request", r.name, False, error=str(e))
    return done


# ---------------------------------------------------------------- customers and items from Zoho

def pages(path, key):
    rows = []
    page = 1
    while page < 200:
        out = zoho("GET", path, params={"page": page, "per_page": 200})
        rows = rows + (out.get(key) or [])
        if not (out.get("page_context") or {}).get("has_more_page"):
            break
        page = page + 1
    return rows


def default(doctype, preferred):
    if preferred and frappe.db.exists(doctype, preferred):
        return preferred
    rows = frappe.get_all(doctype, filters={"is_group": 0} if doctype in ("Customer Group", "Territory", "Item Group") else {},
                          pluck="name", limit=1)
    return rows[0] if rows else None


def sync_customers():
    group = default("Customer Group", frappe.db.get_single_value("Selling Settings", "customer_group"))
    territory = default("Territory", frappe.db.get_single_value("Selling Settings", "territory"))
    made = 0
    linked = 0
    for c in pages("/contacts?contact_type=customer", "contacts"):
        cid = c.get("contact_id")
        if frappe.db.exists("Customer", {"custom_zoho_contact_id": cid}):
            continue
        name = text(c.get("contact_name"))
        existing = frappe.db.get_value("Customer", {"customer_name": name})
        if existing:
            frappe.db.set_value("Customer", existing, "custom_zoho_contact_id", cid, update_modified=False)
            linked = linked + 1
            continue
        frappe.get_doc({"doctype": "Customer", "customer_name": name, "customer_type": "Company",
                        "customer_group": group, "territory": territory,
                        "custom_zoho_contact_id": cid}).insert(ignore_permissions=True)
        made = made + 1
    return {"customers_new": made, "customers_linked": linked}



def sync_items():
    s = settings()
    group = default("Item Group", s.default_item_group)
    uom = "Nos" if frappe.db.exists("UOM", "Nos") else default("UOM", None)
    made = 0
    linked = 0
    missing = []
    for it in pages("/items", "items"):
        iid = it.get("item_id")
        stype = None
        found = frappe.db.get_value("Item", {"custom_zoho_item_id": iid})
        if found:
            continue
        code = text(it.get("sku")) or text(it.get("name"))
        existing = frappe.db.get_value("Item", code) or frappe.db.get_value("Item", {"item_name": text(it.get("name"))})
        if existing:
            values = {"custom_zoho_item_id": iid}
            frappe.db.set_value("Item", existing, values, update_modified=False)
            linked = linked + 1
            continue
        frappe.get_doc({"doctype": "Item", "item_code": code[:140], "item_name": text(it.get("name"))[:140],
                        "item_group": group, "stock_uom": uom, "is_stock_item": 0, "include_item_in_manufacturing": 0,
                        "description": text(it.get("description")) or text(it.get("name")),
                        "standard_rate": flt(it.get("rate")),
                        "custom_zoho_item_id": iid}).insert(ignore_permissions=True)
        made = made + 1
    out = {"items_new": made, "items_linked": linked}
    if missing:
        out["service_types_not_in_eye"] = missing
    return out


def sync_masters():
    out = {}
    try:
        out.update(sync_customers())
        out.update(sync_items())
        log("Sync customers and items", None, None, True, response=out)
    except Exception as e:
        log("Sync customers and items", None, None, False, error=str(e))
        frappe.throw(str(e))
    frappe.db.set_value(SETTINGS, SETTINGS, "last_sync", frappe.utils.now())
    return out


# ---------------------------------------------------------------- runs

def check_all():
    out = {"answers": check_quotes(), "invoices": check_invoices()}
    frappe.db.set_value(SETTINGS, SETTINGS, {"last_check": frappe.utils.now(), "check_requested": 0})
    return out


def tick():
    """Every 5 minutes (Scheduler Event). Calls Zoho only when the webhook asked, once an hour,
    and syncs customers and items once a day."""
    if mode() != "Zoho":
        return "manual"
    s = settings()
    now = frappe.utils.now_datetime()
    out = {}
    hour_ago = str(frappe.utils.add_to_date(now, hours=-1))
    if s.check_requested or not s.last_check or str(s.last_check) < hour_ago:
        out.update(check_all())
    day_ago = str(frappe.utils.add_to_date(now, days=-1))
    if not s.last_sync or str(s.last_sync) < day_ago:
        try:
            out.update(sync_masters())
        except Exception:
            pass
    return out


def retry(log_name):
    require_manager()
    entry = frappe.get_doc("Eye Sync Log", log_name)
    if entry.operation == "Send quote":
        result = push_estimate(entry.reference_name)
    elif entry.operation == "Send invoice request":
        result = push_sales_order(entry.reference_name)
    elif entry.operation == "Sync customers and items":
        result = sync_masters()
    else:
        result = check_all()
    frappe.db.set_value("Eye Sync Log", log_name, "attempts", (entry.attempts or 1) + 1)
    return result


def test():
    require_manager()
    if mode() != "Zoho":
        frappe.throw(_("Set the Accounting System to Zoho first"))
    out = zoho("GET", "/organizations")
    s = settings()
    org = [o for o in out.get("organizations") or [] if str(o.get("organization_id")) == str(s.organization_id)]
    if not org:
        frappe.throw(fmt("Connected, but organization {0} isn't in this Zoho account", [s.organization_id]))
    return {"organization": org[0].get("name"), "currency": org[0].get("currency_code")}


def run(op, f):
    if op == "send_quote":
        return send_quote(f.name)
    if op == "send_invoice_request":
        return send_invoice_request(f.name)
    if op == "tick":
        require_manager()
        return tick()
    if op == "check_now":
        require_manager()
        return check_all()
    if op == "sync_now":
        require_manager()
        return sync_masters()
    if op == "retry":
