    frappe.throw(fmt("Unknown accounting action: {0}", [op]))


frappe.flags.result = run(form.get("op"), form)

# Eye CRM billing: one Billing Request per invoice, drawn from the deal's Sales Order.
#
#   desk:        frappe.call({method: "eye.billing", args: {op: "so_lines", opportunity: ...}})
#                -> r.message.result
#   doc events:  frappe.call("eye.billing", op="br_validate", doc=doc)
#
# Stages: To be invoiced -> Finance, please issue -> Invoiced -> Collected.
# Sales requests and sends to Finance; Finance (Accounts) marks Invoiced and Collected, by hand
# in Manual mode, or eye.books does it from Zoho Books.

TO_INVOICE = "To be invoiced"
TO_FINANCE = "Finance, please issue"
INVOICED = "Invoiced"
COLLECTED = "Collected"
STAGES = [TO_INVOICE, TO_FINANCE, INVOICED, COLLECTED]
DONE = [INVOICED, COLLECTED]
APPROVED_STAGE = "Quote approved"
ACCOUNTS_ROLES = ["Accounts User", "Accounts Manager"]

flt = frappe.utils.flt
form = frappe.form_dict


# ---------------------------------------------------------------- helpers

def fmt(msg, values):
    out = _(msg)
    for i, v in enumerate(values):
        out = out.replace("{" + str(i) + "}", str(v))
    return out


def text(v):
    return " ".join(str(v or "").split())


def money(v, currency):
    return frappe.utils.fmt_money(flt(v), currency=currency)


def has_role(role):
    user = frappe.session.user
    if user == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {"parent": user, "parenttype": "User", "role": role}))


def is_system():
    # each Server Script has its own frappe.flags, so another script can't vouch for a call:
    # automatic answers run as Administrator (the scheduler) and pass the role checks instead
    return False


def is_finance():
    # EYE_FINANCE_ADMIN: Finance steps by Administrator until Zoho Books is connected
    return is_system() or frappe.session.user == "Administrator"


def finance_users():
    users = set(frappe.get_all("Has Role", filters={"role": ["in", ACCOUNTS_ROLES], "parenttype": "User"}, pluck="parent"))
    return [u for u in users if u not in ("Administrator", "Guest") and frappe.db.get_value("User", u, "enabled")]


def notify(user, doctype, name, subject, kind="Alert"):
    if not user or user == frappe.session.user:
        return
    frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": kind, "document_type": doctype,
                    "document_name": name, "subject": subject, "from_user": frappe.session.user}).insert(ignore_permissions=True)


def assign(doctype, name, users, description, date=None):
    for user in set([u for u in users if u]):
        if frappe.db.exists("ToDo", {"allocated_to": user, "reference_type": doctype, "reference_name": name, "status": "Open"}):
            continue
        frappe.get_doc({"doctype": "ToDo", "allocated_to": user, "reference_type": doctype, "reference_name": name,
                        "description": description, "date": date, "assigned_by": frappe.session.user}).insert(ignore_permissions=True)
        notify(user, doctype, name, description, "Assignment")


def close_todos(doctype, name):
    for t in frappe.get_all("ToDo", filters={"reference_type": doctype, "reference_name": name, "status": "Open"}, pluck="name"):
        todo = frappe.get_doc("ToDo", t)
        todo.status = "Closed"
        todo.save(ignore_permissions=True)


def billed_qty(so_detail, exclude=None):
    """Qty of a Sales Order line already in Billing Requests."""
    filters = {"so_detail": so_detail, "parenttype": "Billing Request"}
    if exclude:
        filters["parent"] = ["!=", exclude]
    return sum([flt(r.qty) for r in frappe.get_all("Billing Request Item", filters=filters, fields=["qty"])])


def get_br(name, ptype="read"):
    br = frappe.get_doc("Billing Request", name)
    br.check_permission(ptype)
    return br


# ---------------------------------------------------------------- requesting an invoice

def so_lines(opportunity):
    """The deal's Sales Order lines and what is left to bill on each."""
    opp = frappe.get_doc("Opportunity", opportunity)
    opp.check_permission("read")
    if not opp.custom_sales_order:
        frappe.throw(_("The deal has no Sales Order yet: it is made when Accounts approve the project"))
    so = frappe.get_doc("Sales Order", opp.custom_sales_order)
    rows = []
    for i in so.items:
        left = flt(i.qty) - billed_qty(i.name)
        rows.append({"so_detail": i.name, "item_code": i.item_code, "item_name": i.item_name,
                     "description": frappe.utils.strip_html(i.description or "")[:140],
                     "item_group": i.get("item_group"), "qty": flt(i.qty), "left": left, "rate": flt(i.rate)})
    return {"sales_order": so.name, "currency": so.currency, "rows": rows}


def create(opportunity, rows, expected_date, notes=None, stage=None):
    opp = frappe.get_doc("Opportunity", opportunity)
    opp.check_permission("write")
    if opp.sales_stage != APPROVED_STAGE:
        frappe.throw(_("Invoices are requested once Accounts approve the project"))
    if not opp.custom_sales_order:
        frappe.throw(_("The deal has no Sales Order yet"))
    if not expected_date:
        frappe.throw(_("Set the expected invoice date"))
    rows = json.loads(rows or "[]") if isinstance(rows, str) else rows
    wanted = {}
    for r in rows or []:
        if flt(r.get("qty")) > 0:
            wanted[r.get("so_detail")] = flt(r.get("qty"))
    if not wanted:
        frappe.throw(_("Choose at least one item and its quantity"))
    so = frappe.get_doc("Sales Order", opp.custom_sales_order)
    br = frappe.new_doc("Billing Request")
    br.opportunity = opportunity
    br.sales_order = so.name
    br.expected_date = expected_date
    br.notes = notes
    br.billing_stage = TO_INVOICE
    for i in so.items:
        if i.name in wanted:
            br.append("items", {"so_detail": i.name, "item_code": i.item_code, "qty": wanted[i.name]})
    start = frappe.db.get_value("Billing Stage", {"custom_start_default": 1}, "name") or br.billing_stage
    br.billing_stage = start
    br.insert()
    if stage and stage != start:
        if not frappe.db.get_value("Billing Stage", stage, "custom_can_start_here"):
            frappe.throw(fmt("A request can't start at {0}", [stage]))
        set_stage(br, stage, {})
    return br.name


# ---------------------------------------------------------------- Billing Request events

def fill(doc):
    """Customer, company, currency and each line's item, service type and rate come from the Sales Order."""
    if not doc.sales_order and doc.opportunity:
        doc.sales_order = frappe.db.get_value("Opportunity", doc.opportunity, "custom_sales_order")
    if not doc.sales_order:
        frappe.throw(_("The deal has no Sales Order yet"))
    so = frappe.get_doc("Sales Order", doc.sales_order)
    doc.customer = so.customer
    doc.customer_name = so.customer_name
    doc.company = so.company
    doc.currency = so.currency
    lines = {}
    for i in so.items:
        lines[i.name] = i
    total = 0
    for r in doc.items:
        line = lines.get(r.so_detail)
        if not line:
            frappe.throw(fmt("Row {0}: this item isn't on Sales Order {1}", [r.idx, so.name]))
        r.item_code = line.item_code
        r.item_name = line.item_name
        r.description = frappe.utils.strip_html(line.description or "")[:500]
        r.rate = flt(line.rate)
        r.amount = flt(r.qty) * r.rate
        total = total + r.amount
        if flt(r.qty) <= 0:
            frappe.throw(fmt("Row {0}: the quantity must be more than zero", [r.idx]))
        left = flt(line.qty) - billed_qty(line.name, None if doc.is_new() else doc.name)
        if flt(r.qty) > left + 0.0001:
            frappe.throw(fmt("Row {0}: only {1} of {2} is left to bill", [r.idx, left, line.item_name]))
    doc.total = total


def lines_signature(rows):
    return [[r.so_detail, flt(r.qty)] for r in rows]


def gate(doc, old, new, dry=False):
    """What blocks a stage change: None, or the message."""
    dry = dry or bool(doc.flags.get("nx_skip_required"))
    if old == new:
        return None
    oi = STAGES.index(old) if old in STAGES else -1
    ni = STAGES.index(new) if new in STAGES else -1
    if ni < 0:
        return fmt("{0} isn't a billing stage", [new])
    if ni < oi:
        return None if is_finance() else _("Only Finance moves a billing request back")
    if ni > oi + 1 and not is_system():
        return fmt("Move it one stage at a time: next is {0}", [_(STAGES[oi + 1])])
    if new == TO_FINANCE and not doc.expected_date and not dry:
        return _("Set the expected invoice date first")
    if new == INVOICED:
        if not is_finance():
            return _("Finance marks the invoice as issued")
        if not dry and not (doc.invoice_number and doc.invoice_date):
            return _("Enter the invoice number and date first")
    if new == COLLECTED:
        if not is_finance():
            return _("Finance marks the invoice as collected")
        if not dry and not doc.collected_on:
            return _("Enter the date it was collected first")
    return None


def br_validate(doc):
    before = None if doc.is_new() else doc.get_doc_before_save()
    if doc.is_new():
        doc.billing_stage = doc.billing_stage or TO_INVOICE
        if doc.billing_stage != TO_INVOICE and not is_system():
            frappe.throw(_("A new billing request starts at To be invoiced"))
        opp = frappe.db.get_value("Opportunity", doc.opportunity, ["sales_stage", "custom_sales_order"], as_dict=True)
        if not opp or opp.sales_stage != APPROVED_STAGE:
            frappe.throw(_("Invoices are requested once Accounts approve the project"))
    elif before and before.billing_stage != TO_INVOICE and lines_signature(before.items) != lines_signature(doc.items) and not is_system():
        frappe.throw(_("The items are locked once the request went to Finance"))
    fill(doc)
    if doc.billing_stage == COLLECTED and not flt(doc.collected_amount):
        doc.collected_amount = doc.total
    if not doc.flags.eye_stage and before:
        error = gate(doc, before.billing_stage, doc.billing_stage)
        if error:
            frappe.throw(error, title=fmt("Can't move to {0}", [_(doc.billing_stage)]))


def br_on_update(doc):
    if doc.has_value_changed("billing_stage"):
        if doc.billing_stage == TO_FINANCE:
            frappe.db.set_value("Billing Request", doc.name, "sent_on", frappe.utils.now(), update_modified=False)
            assign("Billing Request", doc.name, finance_users(),
                   fmt("Issue the invoice for {0}: {1}", [doc.customer_name, money(doc.total, doc.currency)]), doc.expected_date)
            frappe.call("eye.books", op="send_invoice_request", name=doc.name)
        elif doc.billing_stage in DONE:
            close_todos("Billing Request", doc.name)
            owner = frappe.db.get_value("Opportunity", doc.opportunity, "owner")
            notify(owner, "Billing Request", doc.name, fmt("{0}: {1}", [doc.customer_name, _(doc.billing_stage)]))
    rollup(doc.opportunity)


def br_on_trash(doc):
    if doc.billing_stage != TO_INVOICE and not has_role("System Manager"):
        frappe.throw(_("Only a request still To be invoiced can be deleted"))
    for t in frappe.get_all("ToDo", filters={"reference_type": "Billing Request", "reference_name": doc.name}, pluck="name"):
        frappe.delete_doc("ToDo", t, ignore_permissions=True, force=True)
    rollup(doc.opportunity, exclude=doc.name)


def rollup(opportunity, exclude=None):
    """The deal's invoiced and collected amounts."""
    filters = {"opportunity": opportunity}
    if exclude:
        filters["name"] = ["!=", exclude]
    billed = 0
    collected = 0
    for r in frappe.get_all("Billing Request", filters=filters, fields=["billing_stage", "total", "collected_amount"]):
        if r.billing_stage in DONE:
            billed = billed + flt(r.total)
        collected = collected + flt(r.collected_amount)
    frappe.db.set_value("Opportunity", opportunity, {"custom_billed_amount": billed, "custom_collected_amount": collected},
                        update_modified=False)


# ---------------------------------------------------------------- Finance (by hand, or from eye.books)

def set_stage(br, stage, values):
    br.update(values)
    br.billing_stage = stage
    br.flags.ignore_permissions = True
    br.save()
    return {"stage": br.billing_stage}


def mark_invoiced(name, invoice_number, invoice_date, zoho_invoice_id=None):
    if not is_finance():
        frappe.throw(_("Finance marks the invoice as issued"))
    if not text(invoice_number) or not invoice_date:
        frappe.throw(_("Enter the invoice number and date"))
    br = frappe.get_doc("Billing Request", name)
    if br.billing_stage not in [TO_FINANCE, INVOICED]:
        frappe.throw(fmt("{0} is {1}, not waiting for Finance", [name, _(br.billing_stage)]))
    values = {"invoice_number": text(invoice_number), "invoice_date": invoice_date}
    if zoho_invoice_id:
        values["zoho_invoice_id"] = zoho_invoice_id
    return set_stage(br, INVOICED, values)


def mark_collected(name, collected_on, amount=None):
    if not is_finance():
        frappe.throw(_("Finance marks the invoice as collected"))
    if not collected_on:
        frappe.throw(_("Enter the date it was collected"))
    br = frappe.get_doc("Billing Request", name)
    if br.billing_stage not in [INVOICED, COLLECTED]:
        frappe.throw(fmt("{0} is {1}: mark it Invoiced first", [name, _(br.billing_stage)]))
    return set_stage(br, COLLECTED, {"collected_on": collected_on, "collected_amount": flt(amount) or br.total})


def record_payment(name, amount, collected_on=None):
    """Part of the invoice is paid (from eye.books): the amount, without changing the stage."""
    if not is_finance():
        frappe.throw(_("Not permitted"))
    br = frappe.get_doc("Billing Request", name)
    frappe.db.set_value("Billing Request", name, {"collected_amount": flt(amount), "collected_on": collected_on}, update_modified=False)
    rollup(br.opportunity)


# ---------------------------------------------------------------- reads for the desk

def steps(br):
    s = []
    s.append({"stage": TO_FINANCE, "key": "ready", "label": _("Items and expected invoice date"),
              "done": len(br.items) > 0 and bool(br.expected_date), "action": "form", "action_label": _("Open"), "waiting_on": None})
    return s


def flow_steps(name):
    return {"field": "billing_stage", "stages": STAGES, "steps": steps(get_br(name))}


def stage_check(name, to):
    br = get_br(name)
    error = gate(br, br.billing_stage, to, True)
    missing = [x for x in steps(br) if x["stage"] == to and not x["done"]] if not error else []
    return {"error": error, "missing": missing, "finance": is_finance()}


DOC_OPS = {
    "br_validate": br_validate,
    "br_on_update": br_on_update,
    "br_on_trash": br_on_trash,
}


def run(op, f):
    if op == "so_lines":
        return so_lines(f.opportunity)
    if op == "create":
        return create(f.opportunity, f.rows, f.expected_date, f.notes, f.get("stage"))
    if op == "mark_invoiced":
        return mark_invoiced(f.name, f.invoice_number, f.invoice_date, f.zoho_invoice_id if has_role("System Manager") else None)
    if op == "mark_collected":
        return mark_collected(f.name, f.collected_on, f.amount)
    if op == "record_payment":
        return record_payment(f.name, f.amount, f.collected_on)
    if op == "flow_steps":
        return flow_steps(f.name)
    if op == "stage_check":
        return stage_check(f.name, f.to)
    frappe.throw(fmt("Unknown billing action: {0}", [op]))


op = form.get("op")
if op in DOC_OPS:
    target = form.get("doc")
    if target is None or isinstance(target, (str, bytes, dict, list)):
        frappe.throw(_("Not permitted"))
    DOC_OPS[op](target)
else:
    frappe.flags.result = run(op, form)

# Eye CRM pricing: every rule and action of the pricing flow lives in this one script.
#
#   desk:          frappe.call({method: "eye.pricing", args: {op: "send_to_sales", name: ...}})
#                  -> the answer is r.message.result
#   doc events:    frappe.call("eye.pricing", op="opp_before_validate", doc=doc)
#
# Ops that change a document (opp_*, pr_*, q_*) take the live document object, so the
# web can't call them: over HTTP `doc` arrives as text.

WITH_PROD = "With Production"
IN_PRICING = "In Pricing"
RETURNED = "Returned to Sales"
PRICED = "Priced"
CHANGE_REQ = "Change Requested"
OPEN = [WITH_PROD, IN_PRICING, RETURNED, CHANGE_REQ]
ACCOUNTS_STAGE = "Finance, please approve"
APPROVED_STAGE = "Quote approved"
STAGES = ["Estimation", "Proposal", "Quotation", "Deals in Hand", ACCOUNTS_STAGE, APPROVED_STAGE]
WON_STAGES = ["Deals in Hand", ACCOUNTS_STAGE, APPROVED_STAGE]
EARLY_STAGES = ["Estimation", "Proposal"]
PO_RECEIVED = "Purchase Order (PO)"
PO_THIS_MONTH = "To receive the PO this month"
ACCOUNTS_ROLES = ["Accounts User", "Accounts Manager"]
MAKE_QUOTATION = "map:erpnext.crm.doctype.opportunity.opportunity.make_quotation"
REQ_FIELDS = ["description", "qty", "notes", "attachment"]
CHANGE_FIELDS = ["description", "qty", "notes"]
LOCKED_COSTING = ["requirement", "description", "qty", "cost", "pricing_request", "custom_base_cost", "custom_original_cost", "custom_original_currency"]
COST_FIELDS = ["sales_item", "sales_item_row", "item_code", "description", "qty", "uom", "rate", "supplier", "notes"]
NUMBERS = ["qty", "rate"]

flt = frappe.utils.flt
cint = frappe.utils.cint
form = frappe.form_dict


# ---------------------------------------------------------------- helpers

def fmt(msg, values):
    out = _(msg)
    for i, v in enumerate(values):
        out = out.replace("{" + str(i) + "}", str(v))
    return out


def text(v):
    return " ".join(str(v or "").split())


def same(a, b, field):
    if field in NUMBERS:
        return flt(a) == flt(b)
    return text(a) == text(b)


def money(v, currency):
    return frappe.utils.fmt_money(flt(v), currency=currency)


def link(doctype, name):
    return frappe.utils.get_link_to_form(doctype, name)


def need_text(v, msg):
    if not text(v):
        frappe.throw(_(msg))


def parse(v):
    if isinstance(v, str):
        return json.loads(v or "null")
    return v


def has_role(role):
    user = frappe.session.user
    if user == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {"parent": user, "parenttype": "User", "role": role}))


def production_users():
    users = set(frappe.get_all("Has Role", filters={"role": "Production", "parenttype": "User"}, pluck="parent"))
    return [u for u in users
            if u not in ("Administrator", "Guest") and frappe.db.get_value("User", u, "enabled")]


def notify(user, doctype, name, subject, kind="Alert"):
    if not user or user == frappe.session.user:
        return
    frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": kind,
                    "document_type": doctype, "document_name": name,
                    "subject": subject, "from_user": frappe.session.user}).insert(ignore_permissions=True)


def assign(doctype, name, users, description, date=None):
    for user in set([u for u in users if u]):
        open_todo = {"allocated_to": user, "reference_type": doctype, "reference_name": name, "status": "Open"}
        if frappe.db.exists("ToDo", open_todo):
            continue
        frappe.get_doc({"doctype": "ToDo", "allocated_to": user, "reference_type": doctype,
                        "reference_name": name, "description": description, "date": date,
                        "assigned_by": frappe.session.user}).insert(ignore_permissions=True)
        notify(user, doctype, name, description, "Assignment")


def close_todos(doctype, name):
    filters = {"reference_type": doctype, "reference_name": name, "status": "Open"}
    for t in frappe.get_all("ToDo", filters=filters, pluck="name"):
        todo = frappe.get_doc("ToDo", t)
        todo.status = "Closed"
        todo.save(ignore_permissions=True)


def delete_todos(doctype, name):
    for t in frappe.get_all("ToDo", filters={"reference_type": doctype, "reference_name": name}, pluck="name"):
        frappe.delete_doc("ToDo", t, ignore_permissions=True, force=True)


def opp_owner(pr):
    return frappe.db.get_value("Opportunity", pr.opportunity, "owner")


def set_opp_status(opportunity, status):
    frappe.db.set_value("Opportunity", opportunity, "custom_pricing_status", status, update_modified=False)


def open_request(opportunity, exclude=None):
    filters = {"opportunity": opportunity, "status": ["in", OPEN]}
    if exclude:
        filters["name"] = ["!=", exclude]
    return frappe.db.get_value("Pricing Request", filters)


def sales_started(pr):
    return cint(frappe.db.get_value("Pricing Request", pr.name, "sales_started"))


def costs_signature(rows):
    out = []
    for r in rows:
        out.append([flt(r.get(f)) if f in NUMBERS else text(r.get(f)) for f in COST_FIELDS])
    return out


def change_status(pr):
    return frappe.db.get_value("Pricing Change", pr.pending_change, "status") if pr.pending_change else None


def change_is_draft(pr):
    return change_status(pr) == "Draft"


def save_opp(opp, flags=None):
    opp.flags.eye_pricing = True
    opp.flags.ignore_permissions = True
    opp.flags.ignore_mandatory = True
    for k in (flags or {}):
        opp.flags[k] = flags[k]
    opp.save()


def label(line):
    return str(line.idx) + " · " + text(line.get("custom_sales_item") or line.description)


def items_total(opp):
    return sum([flt(i.amount) or flt(i.qty) * flt(i.rate) for i in opp.items])


def locked_requirements(opportunity):
    prs = frappe.get_all("Pricing Request", filters={"opportunity": opportunity, "status": ["!=", WITH_PROD]}, pluck="name")
    if not prs:
        return []
    return frappe.get_all("Pricing Request Item", filters={"parent": ["in", prs]}, pluck="requirement")


def needs_production(r):
    """A line goes to Production unless its item is in the Service group."""
    code = r.get("item_code")
    if not code:
        return True
    return frappe.db.get_value("Item", code, "item_group") != "Service"


def company_currency(company):
    return frappe.db.get_value("Company", company, "default_currency") if company else None


def rate_to(cur, base, date=None):
    if not cur or not base or cur == base:
        return 1.0
    return flt(frappe.call("erpnext.setup.utils.get_exchange_rate", from_currency=cur, to_currency=base,
                           transaction_date=date or frappe.utils.nowdate())) or 1.0


def pricing_status(opp, ignore_pr=None):
    if not opp.is_new():
        filters = {"opportunity": opp.name, "status": ["in", OPEN]}
        if ignore_pr:
            filters["name"] = ["!=", ignore_pr]
        status = frappe.db.get_value("Pricing Request", filters, "status")
        if status:
            return status
    priced = set([c.requirement for c in opp.custom_costing])
    if opp.custom_requirements and all([r.name in priced or not needs_production(r) for r in opp.custom_requirements]):
        return PRICED
    return None


def get_opp(name, ptype="read"):
    opp = frappe.get_doc("Opportunity", name)
    opp.check_permission(ptype)
    return opp


def for_production(name, allowed):
    pr = frappe.get_doc("Pricing Request", name)
    if not has_role("Production"):
        frappe.throw(_("Only Production can do this"))
    if pr.status not in allowed:
        frappe.throw(fmt("Not possible while the request is {0}", [_(pr.status)]))
    return pr


def check_all_priced(pr):
    missing = [str(r.idx) for r in pr.items if flt(r.cost) <= 0]
    if missing:
        frappe.throw(fmt("Add cost elements for lines: {0}", [", ".join(missing)]))


def original_cost(pr, requirement):
    """The requirement's cost as Production entered it: one amount per currency."""
    by_cur = {}
    order = []
    for c in pr.costs:
        if c.sales_item_row != requirement:
            continue
        cur = c.get("custom_currency") or pr.currency
        if cur not in by_cur:
            by_cur[cur] = 0.0
            order.append(cur)
        by_cur[cur] = by_cur[cur] + flt(c.amount)
    return " + ".join([frappe.utils.fmt_money(by_cur[cur], currency=cur) for cur in order])


def one_currency(pr, requirement):
    curs = set([c.get("custom_currency") or pr.currency for c in pr.costs if c.sales_item_row == requirement])
    return list(curs)[0] if len(curs) == 1 else None


def apply_to_opportunity(pr):
    opp = frappe.get_doc("Opportunity", pr.opportunity)
    existing = {}
    for c in opp.custom_costing:
        existing[c.requirement] = c
    live = set([r.name for r in opp.custom_requirements])
    for line in pr.items:
        if line.requirement not in live:
            continue
        row = existing.get(line.requirement)
        if row and row.pricing_request and row.pricing_request != pr.name:
            continue
        if not row:
            row = opp.append("custom_costing", {"requirement": line.requirement, "margin": 0})  # Sales sets the margin by hand
        row.update({"description": line.description, "qty": line.qty, "cost": flt(line.cost) / (flt(opp.conversion_rate) or 1), "custom_base_cost": line.cost, "custom_original_cost": original_cost(pr, line.requirement), "custom_original_currency": one_currency(pr, line.requirement), "pricing_request": pr.name})
    save_opp(opp)


def restore_costs(pr):
    pr.set("costs", [])
    for c in json.loads(pr.approved_costs or "[]"):
        pr.append("costs", c)
    pr.status = PRICED
    pr.pending_change = None
    pr.approved_costs = None
    pr.flags.eye_system = True
    pr.save(ignore_permissions=True)
    set_opp_status(pr.opportunity, PRICED)


def cost_breakdown(opp):
    out = {}
    for c in opp.custom_costing:
        if not c.pricing_request:
            continue
        out[c.requirement] = frappe.get_all(
            "Pricing Request Cost",
            filters={"parent": c.pricing_request, "sales_item_row": c.requirement},
            fields=["item_code", "description", "qty", "rate", "amount", "supplier"],
            order_by="idx")
    return out


# ---------------------------------------------------------------- Opportunity events

def opp_before_validate(doc):
    before = doc.get_doc_before_save()

    # requirements Production already started on change only through a Pricing Change
    if before and not doc.flags.eye_allow_req_change:
        locked = set(locked_requirements(doc.name))
        new_req = {}
        for r in doc.custom_requirements:
            new_req[r.name] = r
        for o in before.custom_requirements:
            if o.name not in locked:
                continue
            r = new_req.get(o.name)
            if not r or not all([same(r.get(f), o.get(f), f) for f in REQ_FIELDS]):
                frappe.throw(fmt("Requirement {0} is already with Production. Use Request Change", [o.idx]))

    # costing rows come only from Production; Sales may change the margin only
    old_cost = {}
    if before:
        for r in before.custom_costing:
            old_cost[r.name] = r
    if not doc.flags.eye_pricing:
        direct = set([r.name for r in doc.custom_requirements if not needs_production(r)])
        keep = []
        for r in doc.custom_costing:
            if r.requirement in direct and not r.pricing_request:
                keep.append(r)
                continue
            o = old_cost.get(r.name)
            if not o:
                continue
            for f in LOCKED_COSTING:
                r.set(f, o.get(f))
            keep.append(r)
        doc.set("custom_costing", keep)

    base_cur = company_currency(doc.company)
    if not doc.currency:
        doc.currency = base_cur
    if not base_cur or doc.currency == base_cur:
        doc.conversion_rate = 1
    elif doc.has_value_changed("currency") or flt(doc.conversion_rate) in (0, 1):
        doc.conversion_rate = rate_to(doc.currency, base_cur, doc.transaction_date)
    conv = flt(doc.conversion_rate) or 1
    for c in doc.custom_costing:
        if c.pricing_request and flt(c.get("custom_base_cost")):
            c.cost = flt(c.custom_base_cost) / conv
        else:
            c.custom_base_cost = flt(c.cost) * conv
    live = set([r.name for r in doc.custom_requirements])
    doc.set("custom_costing", [c for c in doc.custom_costing if c.requirement in live])

    # the first margin Sales saves means Sales started on those costs
    started = set()
    for c in doc.custom_costing:
        o = old_cost.get(c.name)
        if o and flt(o.margin) != flt(c.margin) and c.pricing_request:
            started.add(c.pricing_request)
        if flt(c.cost) > 0:
            # EYE_SELL_OR_MARGIN: Sales types margin OR selling
            o_sel = flt(o.selling) if o else 0
            o_mar = flt(o.margin) if o else 0
            o_cst = flt(o.cost) if o else 0
            sel_chg = flt(c.selling) != o_sel
            mar_chg = flt(c.margin) != o_mar
            if sel_chg and not mar_chg and flt(c.selling) > 0:
                c.margin = flt((flt(c.selling) / flt(c.cost) - 1) * 100, 2)
            elif mar_chg or flt(c.cost) != o_cst or not o:
                want = flt(c.cost) * (1 + flt(c.margin) / 100) if flt(c.margin) > 0 else 0
                diff = want - flt(c.selling)
                if not (sel_chg and flt(c.selling) > 0 and diff < 1 and diff > -1):
                    c.selling = want
        elif flt(c.selling) > 0:
            c.margin = 100
    for pr in started:
        if not frappe.db.get_value("Pricing Request", pr, "sales_started"):
            frappe.db.set_value("Pricing Request", pr, "sales_started", 1, update_modified=False)

    doc.custom_total_cost = sum([flt(c.cost) for c in doc.custom_costing])
    doc.custom_total_selling = sum([flt(c.selling) for c in doc.custom_costing])
    doc.custom_pricing_status = pricing_status(doc, doc.flags.eye_ignore_pr)
    sync_items(doc)
    if items_total(doc) > 0:
        doc.opportunity_amount = items_total(doc)
    doc.base_opportunity_amount = flt(doc.opportunity_amount) * conv


def sync_items(doc):
    """A requirement with a sales item, priced by Production and given a margin, is a line in
    Items: same item, description and qty, at the selling price. The line follows the cost and
    the margin; lines added by hand (no requirement) are left alone. The quotation is made
    from Items, so it gets them as they are."""
    costing = {}
    for c in doc.custom_costing:
        costing[c.requirement] = c
    ready = {}
    order = []
    for r in doc.custom_requirements:
        c = costing.get(r.name)
        if r.get("item_code") and c and flt(c.selling) > 0:
            ready[r.name] = [r, c]
            order.append(r.name)
    keep = []
    done = set()
    for i in doc.items:
        key = i.get("custom_requirement")
        if not key:
            keep.append(i)
            continue
        if key not in ready or key in done:
            continue  # its requirement went, lost its item, or isn't priced any more
        i.update(item_values(i, ready[key][0], ready[key][1]))
        keep.append(i)
        done.add(key)
    for key in order:
        if key in done:
            continue
        row = {"custom_requirement": key}
        row.update(item_values(row, ready[key][0], ready[key][1]))
        keep.append(row)
    doc.set("items", keep)


def item_values(row, req, cost):
    qty = flt(req.qty) or 1
    item = frappe.db.get_value("Item", req.item_code, ["item_name", "stock_uom", "item_group"], as_dict=True) or {}
    same = row.get("item_code") == req.item_code
    return {
        "item_code": req.item_code,
        "item_name": row.get("item_name") if same and row.get("item_name") else item.get("item_name"),
        "description": req.description or item.get("item_name"),
        "qty": qty,
        "uom": row.get("uom") if same and row.get("uom") else item.get("stock_uom"),
        "rate": flt(cost.selling) / qty,
        "amount": flt(cost.selling),
        "item_group": item.get("item_group"),
    }


def opp_on_update(doc):
    if doc.sales_stage == ACCOUNTS_STAGE and doc.has_value_changed("sales_stage") and not doc.flags.eye_stage:
        request_approval(doc)

    # a request Production has not started follows the requirements as Sales edits them
    reqs = {}
    for r in doc.custom_requirements:
        reqs[r.name] = r
    for name in frappe.get_all("Pricing Request", filters={"opportunity": doc.name, "status": WITH_PROD}, pluck="name"):
        pr = frappe.get_doc("Pricing Request", name)
        keep = []
        changed = False
        for line in pr.items:
            r = reqs.get(line.requirement)
            if not r:
                changed = True
                continue
            for f in REQ_FIELDS:
                if not same(line.get(f), r.get(f), f):
                    line.set(f, r.get(f))
                    changed = True
            keep.append(line)
        if not changed:
            continue
        if keep:
            pr.set("items", keep)
            pr.flags.eye_system = True
            pr.save(ignore_permissions=True)
            continue
        # every line of the request was removed: the request goes too
        frappe.delete_doc("Pricing Request", name, ignore_permissions=True, force=True)
        doc.custom_pricing_status = pricing_status(doc, name)
        set_opp_status(doc.name, doc.custom_pricing_status)


# ---------------------------------------------------------------- deal stages
#
# Eye checks its own stages: opp_validate runs Before Save, so the form, the Kanban, the List
# and the API all obey it. The desk asks stage_check (what a move still needs) and
# flow_steps (every stage's steps, for the Flow screen); both read deal_steps, so a step is
# written once.

def is_system():
    # each Server Script has its own frappe.flags, so another script can't vouch for a call:
    # automatic answers run as Administrator (the scheduler) and pass the role checks instead
    return False


def has_any_role(roles):
    return any([has_role(r) for r in roles])


def latest_quotation(opportunity):
    rows = frappe.get_all("Quotation", filters={"opportunity": opportunity, "docstatus": ["<", 2]},
                          fields=["name", "docstatus"], order_by="modified desc", limit=1)
    return rows[0] if rows else None


def items_above_minimum(opp):
    return len(opp.items) > 0 and items_total(opp) + 0.005 >= flt(opp.custom_total_selling)


def step(stage, key, label, done, action="", action_label="", waiting_on=None):
    return {"stage": stage, "key": key, "label": _(label), "done": bool(done), "action": action,
            "action_label": _(action_label) if action_label else "", "waiting_on": _(waiting_on) if waiting_on else None}



def gate_waiting(steps):
    """A step that waits on someone holds the steps after it in the same stage: no buttons there yet."""
    if not isinstance(steps, list):
        return steps
    held = {}
    for x in steps:
        if not isinstance(x, dict):
            continue
        st = x.get("stage")
        if x.get("done"):
            continue
        if st in held:
            x["action"] = None
            x["action_label"] = None
            if not x.get("waiting_on"):
                x["waiting_on"] = held[st]
        elif x.get("waiting_on"):
            held[st] = x.get("waiting_on")
    return steps

def deal_steps(opp):
    """Every stage's steps, in order. Each stage lists only its own steps."""
    out = []
    # fields a stage needs are set on the fields themselves (Mandatory Depends On, in Customize
    # Form); here only the steps of the process, which no field setting can express
    status = opp.custom_pricing_status
    cost_of = {}
    for c in opp.custom_costing:
        cost_of[c.requirement] = c
    margins = len(opp.custom_requirements) > 0 and all(
        [bool(cost_of.get(r.name)) and flt(cost_of[r.name].selling) > 0 for r in opp.custom_requirements])
    above = items_above_minimum(opp)
    quotation = None if opp.is_new() else latest_quotation(opp.name)
    out.append(step("Proposal", "requirements", "Services added", len(opp.custom_requirements) > 0,
                    "fields:custom_requirements,custom_pricing_required_by,custom_pricing_notes", "Add services"))
    with_item = len(opp.custom_requirements) > 0 and all([r.get("item_code") for r in opp.custom_requirements])
    out.append(step("Proposal", "items", "A service on every line", with_item,
                    "fields:custom_requirements", "Set services"))
    out.append(step("Proposal", "sent", "Pass-through lines sent to Production", status,
                    "send_to_production", "Send to Production"))
    out.append(step("Proposal", "priced", "Production finished the pricing", status == PRICED, "", "",
                    "Production" if status and status != PRICED else None))
    out.append(step("Proposal", "margin", "P&L done: a selling price on every line", margins, "create_pl", "Create P&L"))
    out.append(step("Deals in Hand", "quotation", "Quotation created", quotation, "create_quotation", "Create Quotation"))

    out.append(step("Deals in Hand", "items_won", "Items still at or above the minimum", above, "fields:items", "Edit Items"))
    out.append(step(APPROVED_STAGE, "approval", "Accounts approved the project",
                    opp.custom_accounts_approval == "Approved", "form", "Open Deal", "Accounts"))
    return gate_waiting(out)


def stage_index(stage):
    return STAGES.index(stage) if stage in STAGES else -1


def gate(opp, old, new):
    """What blocks a move from `old` to `new`: {"error": text} or {"missing": [steps]}."""
    oi = stage_index(old)
    ni = stage_index(new)
    if ni < 0 or old == new:
        return {"missing": []}
    if ni < oi:
        if old in [ACCOUNTS_STAGE, APPROVED_STAGE] and not is_system() and not has_role("System Manager"):
            return {"error": fmt("The deal is {0}: only Accounts' answer moves it back.", [_(old)])}
        return {"missing": []}
    wanted = STAGES[oi + 1:ni + 1]
    return {"missing": [s for s in deal_steps(opp) if s["stage"] in wanted and not s["done"]
                        and not (s["key"] == "quotation" and ni > stage_index("Quotation"))]}


def action_button(s, doctype, name):
    esc = frappe.utils.escape_html
    return ('<button class="btn btn-xs btn-primary" data-nx-action="' + esc(s["action"]) + '" data-doctype="'
            + esc(doctype) + '" data-name="' + esc(name) + '">' + esc(s["action_label"] or _("Open")) + "</button>")


def gate_message(doctype, name, target, res):
    if res.get("error"):
        return res["error"]
    esc = frappe.utils.escape_html
    rows = ""
    for s in res["missing"]:
        wait = ' <span class="text-muted">(' + fmt("waiting on {0}", [s["waiting_on"]]) + ")</span>" if s["waiting_on"] else ""
        rows += "<li>" + esc(s["label"]) + wait + "</li>"
    first = [s for s in res["missing"] if s["action"] and not s["waiting_on"]]
    button = action_button(first[0], doctype, name) if first and name else ""
    return fmt("Can't move to {0} yet:", [_(target)]) + "<ul>" + rows + "</ul>" + button


def opp_validate(doc):
    if doc.flags.eye_stage or not doc.has_value_changed("sales_stage"):
        return
    before = doc.get_doc_before_save()
    res = gate(doc, before.sales_stage if before else None, doc.sales_stage)
    if res.get("error") or res["missing"]:
        frappe.throw(gate_message("Opportunity", None if doc.is_new() else doc.name, doc.sales_stage, res),
                     title=fmt("Can't move to {0} yet", [_(doc.sales_stage)]))


def stage_check(name, to):
    opp = get_opp(name)
    res = gate(opp, opp.sales_stage, to)
    return {"error": res.get("error"), "missing": res.get("missing") or [],
            "message": gate_message("Opportunity", name, to, res) if res.get("error") or res.get("missing") else None}


def flow_steps(name):
    return {"field": "sales_stage", "stages": STAGES, "steps": deal_steps(get_opp(name))}


# ---------------------------------------------------------------- Accounts approval
#
# Entering "Finance, please approve" asks Accounts (a ToDo, and the quote goes to the
# accounting system through eye.books). Their answer moves the deal: approved to
# "Quote approved" with a Sales Order, or back to "Deals in Hand" with the reason.

def accounts_users():
    users = set(frappe.get_all("Has Role", filters={"role": ["in", ACCOUNTS_ROLES], "parenttype": "User"}, pluck="parent"))
    return [u for u in users if u not in ("Administrator", "Guest") and frappe.db.get_value("User", u, "enabled")]


def can_answer():
    return is_system() or has_role("System Manager") or has_role("Sales Manager") or has_any_role(ACCOUNTS_ROLES)


def request_approval(doc):
    frappe.db.set_value("Opportunity", doc.name, {"custom_accounts_approval": "Pending", "custom_approval_note": None,
                                                 "custom_approved_by": None, "custom_approved_on": None},
                        update_modified=False)
    close_todos("Opportunity", doc.name)
    assign("Opportunity", doc.name, accounts_users(), fmt("Approve the project {0}", [doc.customer_name or doc.name]))
    frappe.call("eye.books", op="send_quote", name=doc.name)


def answered_by():
    user = frappe.session.user
    return None if user == "Guest" else user


def waiting_deal(name):
    if not can_answer():
        frappe.throw(_("Only Accounts can answer this"))
    opp = frappe.get_doc("Opportunity", name)
    if opp.sales_stage != ACCOUNTS_STAGE:
        frappe.throw(fmt("{0} is {1}, not waiting for Accounts", [name, _(opp.sales_stage)]))
    return opp


def approve_project(name, note=None):
    opp = waiting_deal(name)
    frappe.db.set_value("Opportunity", name, {"custom_accounts_approval": "Approved", "custom_approval_note": text(note) or None,
                                             "custom_approved_by": answered_by(), "custom_approved_on": frappe.utils.now(),
                                             "sales_stage": APPROVED_STAGE})
    opp.add_comment("Info", _("Accounts approved the project") + (": " + text(note) if text(note) else ""))
    close_todos("Opportunity", name)
    notify(opp.owner, "Opportunity", name, fmt("Accounts approved {0}", [opp.customer_name or name]))
    sales_order = None
    error = None
    try:
        sales_order = make_sales_order(name)
    except Exception as e:
        error = frappe.utils.strip_html(str(e))[:300]
        opp.add_comment("Comment", fmt("Sales Order not created: {0}", [error]))
    return {"stage": APPROVED_STAGE, "sales_order": sales_order, "error": error}


def reject_project(name, reason):
    need_text(reason, "Write why the project isn't approved")
    opp = waiting_deal(name)
    frappe.db.set_value("Opportunity", name, {"custom_accounts_approval": "Rejected", "custom_approval_note": text(reason),
                                             "custom_approved_by": answered_by(), "custom_approved_on": frappe.utils.now(),
                                             "sales_stage": "Deals in Hand"})
    opp.add_comment("Info", fmt("Accounts didn't approve the project: {0}", [text(reason)]))
    close_todos("Opportunity", name)
    assign("Opportunity", name, [opp.owner],
           fmt("Accounts didn't approve {0}: {1}", [opp.customer_name or name, text(reason)]))
    return {"stage": "Deals in Hand"}


def make_sales_order(name):
    """The deal's Sales Order, from its quotation (submitted first if it is still a draft)."""
    opp = frappe.get_doc("Opportunity", name)
    if opp.custom_sales_order and frappe.db.exists("Sales Order", {"name": opp.custom_sales_order, "docstatus": ["<", 2]}):
        return opp.custom_sales_order
    if opp.sales_stage != APPROVED_STAGE:
        frappe.throw(_("A Sales Order is made once Accounts approve the project"))
    q = latest_quotation(name)
    if not q:
        frappe.throw(_("The deal has no quotation"))
    quotation = frappe.get_doc("Quotation", q.name)
    if quotation.docstatus == 0:
        quotation.flags.ignore_permissions = True
        quotation.submit()
    so = frappe.call("erpnext.selling.doctype.quotation.quotation.make_sales_order", source_name=quotation.name)
    today = frappe.utils.nowdate()
    when = frappe.utils.add_days(today, 30)
    if opp.expected_closing and str(opp.expected_closing) >= today:
        when = opp.expected_closing
    so.delivery_date = when
    for i in so.items:
        i.delivery_date = i.delivery_date or when
    if opp.custom_po_no:
        so.po_no = opp.custom_po_no
    so.flags.ignore_permissions = True
    so.insert()
    so.submit()
    frappe.db.set_value("Opportunity", name, "custom_sales_order", so.name, update_modified=False)
    opp.add_comment("Info", fmt("Sales Order {0} created", [so.name]))
    return so.name


def retry_sales_order(name):
    if not (can_answer() or has_role("Sales User")):
        frappe.throw(_("Not permitted"))
    get_opp(name)
    return make_sales_order(name)


# ---------------------------------------------------------------- Pricing Request events

def check_cost_edit_allowed(pr):
    if pr.status == WITH_PROD and has_role("Production"):
        # the first cost Production saves starts the pricing
        pr.status = IN_PRICING
        pr.flags.eye_started = True
        return
    if pr.status == IN_PRICING:
        return
    if pr.status == PRICED and not sales_started(pr):
        return
    if pr.status == CHANGE_REQ and change_is_draft(pr):
        return
    messages = {
        WITH_PROD: "Only Production can add the costs",
        RETURNED: "Waiting for Sales to answer your question",
        CHANGE_REQ: "Sales hasn't allowed your change yet" if change_status(pr) == "Requested"
        else "Your change is waiting for Sales approval",
        PRICED: "Sales already started on these costs. Use Request Change",
    }
    frappe.throw(_(messages.get(pr.status, "These costs cannot be changed now")))


def pr_validate(doc):
    if doc.is_new():
        other = open_request(doc.opportunity, doc.name)
        if other:
            frappe.throw(fmt("Pricing Request {0} is still open", [link("Pricing Request", other)]))
        doc.status = doc.status or WITH_PROD
    elif not doc.flags.eye_system:
        stage = frappe.db.get_value("Opportunity", doc.opportunity, "sales_stage")
        if stage in WON_STAGES and not has_role("System Manager"):
            frappe.throw(fmt("The deal is {0}; this pricing is locked", [_(stage)]))
        before = doc.get_doc_before_save()
        if before and costs_signature(before.costs) != costs_signature(doc.costs):
            check_cost_edit_allowed(doc)

    by_idx = {}
    totals = {}
    for r in doc.items:
        by_idx[r.idx] = r
        totals[r.requirement] = 0.0
    base_cur = company_currency(frappe.db.get_value("Opportunity", doc.opportunity, "company"))
    doc.custom_company_currency = base_cur
    if not doc.currency:
        doc.currency = base_cur
    for c in doc.costs:
        head = text(c.sales_item).split("·")[0].strip()
        line = by_idx.get(cint(head)) if head.isdigit() else None
        if line:
            c.sales_item_row = line.requirement
            c.sales_item = label(line)
        elif c.sales_item_row not in totals:
            frappe.throw(fmt("Cost row {0}: choose which line it belongs to", [c.idx]))
        c.amount = flt(c.qty) * flt(c.rate)
        cur = c.get("custom_currency") or doc.currency or base_cur
        c.custom_currency = cur
        if cur == base_cur:
            c.custom_exchange_rate = 1
        elif not flt(c.get("custom_exchange_rate")):
            c.custom_exchange_rate = rate_to(cur, base_cur)
        c.custom_base_amount = c.amount * flt(c.custom_exchange_rate)
        totals[c.sales_item_row] = totals[c.sales_item_row] + flt(c.custom_base_amount)

    for r in doc.items:
        r.cost = totals.get(r.requirement, 0)
    doc.total_cost = sum([flt(r.cost) for r in doc.items])

    if doc.status == PRICED:
        check_all_priced(doc)
        if not doc.priced_on:
            doc.priced_on = frappe.utils.now()


def pr_after_insert(doc):
    set_opp_status(doc.opportunity, WITH_PROD)
    assign("Pricing Request", doc.name, production_users(),
           fmt("Pricing needed: {0}", [doc.customer_name or doc.opportunity]), doc.required_by)


def pr_on_update(doc):
    if doc.flags.eye_started:
        set_opp_status(doc.opportunity, IN_PRICING)
        doc.add_comment("Comment", _("Started pricing"))
        return
    # priced and Sales has not started yet: Production's edits flow straight to the deal
    if doc.status != PRICED or doc.flags.eye_system or sales_started(doc):
        return
    before = doc.get_doc_before_save()
    if before and before.status == PRICED and costs_signature(before.costs) != costs_signature(doc.costs):
        apply_to_opportunity(doc)
        notify(opp_owner(doc), "Opportunity", doc.opportunity,
               fmt("Production updated the costs of {0}", [doc.customer_name or doc.opportunity]))


def pr_on_trash(doc):
    if doc.status != WITH_PROD and not has_role("System Manager"):
        frappe.throw(_("Only a request that Production has not started can be deleted"))
    delete_todos("Pricing Request", doc.name)
    opp = frappe.get_doc("Opportunity", doc.opportunity)
    if [c for c in opp.custom_costing if c.pricing_request == doc.name]:
        opp.set("custom_costing", [c for c in opp.custom_costing if c.pricing_request != doc.name])
        save_opp(opp, {"eye_ignore_pr": doc.name})
    else:
        set_opp_status(opp.name, pricing_status(opp, doc.name))


# ---------------------------------------------------------------- Quotation events

def q_validate(doc):
    if not doc.opportunity or doc.docstatus == 2:
        return
    opp = frappe.db.get_value("Opportunity", doc.opportunity,
                              ["custom_pricing_status", "custom_total_selling", "currency", "conversion_rate"], as_dict=True)
    if not opp:
        return
    if opp.custom_pricing_status != PRICED:
        frappe.throw(fmt("Pricing of {0} is not finished yet", [link("Opportunity", doc.opportunity)]))
    if frappe.db.exists("Opportunity Costing", {"parent": doc.opportunity, "parenttype": "Opportunity", "margin": ["<=", 0]}) or frappe.db.exists("Opportunity Costing", {"parent": doc.opportunity, "parenttype": "Opportunity", "selling": ["<=", 0]}):
        frappe.throw(fmt("Set a selling price on every line in {0} before the quotation", [link("Opportunity", doc.opportunity)]))
    minimum = flt(opp.custom_total_selling)
    total = flt(doc.net_total)
    currency = doc.currency
    if doc.currency != opp.currency:
        total = flt(doc.base_net_total)
        currency = frappe.db.get_value("Company", doc.company, "default_currency")
        minimum = minimum * (flt(opp.conversion_rate) or 1)
    if total + 0.005 < minimum:
        frappe.throw(fmt("Net total {0} is less than the minimum selling total {1}",
                         [money(total, currency), money(minimum, currency)]))


def q_on_update(doc):
    if not doc.opportunity or doc.docstatus == 2:
        return
    stage = frappe.db.get_value("Opportunity", doc.opportunity, "sales_stage")
    if stage and stage not in EARLY_STAGES:
        return
    frappe.db.set_value("Opportunity", doc.opportunity, "sales_stage", "Quotation", update_modified=False)
    frappe.get_doc("Opportunity", doc.opportunity).add_comment(
        "Info", fmt("Moved to Quotation: {0} was saved", [doc.name]))


# ---------------------------------------------------------------- Sales actions


def send_to_production(opportunity):
    opp = get_opp(opportunity, "write")
    if not opp.custom_pricing_required_by:
        frappe.throw(_("Set Required By in the Pricing tab first"))
    other = open_request(opp.name)
    if other:
        frappe.throw(fmt("Pricing Request {0} is still open", [link("Pricing Request", other)]))
    priced = set([c.requirement for c in opp.custom_costing])
    rows = [r for r in opp.custom_requirements if r.name not in priced and needs_production(r)]
    if not rows:
        frappe.throw(_("Nothing to send: no new lines that need Production"))
    pr = frappe.get_doc({
        "doctype": "Pricing Request",
        "opportunity": opp.name,
        "customer_name": opp.customer_name or opp.party_name,
        "currency": opp.currency or company_currency(opp.company),
        "required_by": opp.custom_pricing_required_by,
        "sales_notes": opp.custom_pricing_notes,
        "status": WITH_PROD,
        "items": [{"requirement": r.name, "description": r.description, "qty": r.qty,
                   "notes": r.notes, "attachment": r.attachment} for r in rows],
    }).insert()
    return pr.name


def reply_to_production(name, reply):
    pr = frappe.get_doc("Pricing Request", name)
    get_opp(pr.opportunity, "write")
    if pr.status != RETURNED:
        frappe.throw(_("This request is not waiting for a reply"))
    need_text(reply, "Write the reply for Production")
    pr.db_set({"status": IN_PRICING, "sales_reply": reply})
    set_opp_status(pr.opportunity, IN_PRICING)
    close_todos("Pricing Request", pr.name)
    assign("Pricing Request", pr.name, production_users(), fmt("Sales replied: {0}", [reply]), pr.required_by)
    pr.add_comment("Comment", fmt("Sales replied: {0}", [reply]))


def request_requirement_change(opportunity, requirement, reason, description, qty, notes):
    opp = get_opp(opportunity, "write")
    need_text(reason, "Write the reason")
    row = None
    for r in opp.custom_requirements:
        if r.name == requirement:
            row = r
    if not row:
        frappe.throw(_("Requirement not found"))

    pr_name = frappe.db.get_value("Pricing Request Item", {"requirement": requirement}, "parent", order_by="creation desc")
    if not pr_name or frappe.db.get_value("Pricing Request", pr_name, "status") == WITH_PROD:
        frappe.throw(_("Production has not started on this line; edit it directly"))
    pr = frappe.get_doc("Pricing Request", pr_name)
    if pr.pending_change:
        frappe.throw(fmt("There is already a pending change on {0}", [pr.name]))

    new = {"requirement": requirement, "description": description,
           "qty": flt(qty) if qty not in (None, "") else row.qty, "notes": notes}
    lines = []
    for f in CHANGE_FIELDS:
        if not same(row.get(f), new.get(f), f):
            lines.append({"line": label(row), "field": _(f.title()),
                          "old_value": str(row.get(f) or ""), "new_value": str(new.get(f) or "")})
    if not lines:
        frappe.throw(_("Nothing changed"))

    change = frappe.get_doc({
        "doctype": "Pricing Change", "pricing_request": pr.name, "opportunity": opp.name,
        "requested_by_side": "Sales", "status": "Pending", "reason": reason, "lines": lines,
        "payload": json.dumps(new, default=str),
    }).insert(ignore_permissions=True)
    pr.db_set("pending_change", change.name)
    assign("Pricing Change", change.name, production_users(), fmt("Sales asks to change a requirement: {0}", [reason]))
    return change.name


