def request_cost_change(name, reason):
    pr = for_production(name, [PRICED])
    if not sales_started(pr):
        frappe.throw(_("Sales has not started yet; edit the costs directly"))
    need_text(reason, "Write the reason")
    snapshot = json.dumps([dict([(f, c.get(f)) for f in COST_FIELDS + ["custom_currency", "custom_exchange_rate", "custom_base_amount"]]) for c in pr.costs], default=str)
    change = frappe.get_doc({"doctype": "Pricing Change", "pricing_request": pr.name, "opportunity": pr.opportunity,
                             "requested_by_side": "Production", "status": "Requested",
                             "reason": reason}).insert(ignore_permissions=True)
    pr.db_set({"status": CHANGE_REQ, "pending_change": change.name, "approved_costs": snapshot})
    set_opp_status(pr.opportunity, CHANGE_REQ)
    pr.add_comment("Comment", fmt("Change requested: {0}", [reason]))
    # the costs stay locked until Sales allows the change
    assign("Pricing Change", change.name, [opp_owner(pr)],
           fmt("Production asks to change the costs: {0}", [reason]))


def allow_change(name, response):
    """Sales lets Production edit the costs; the edited costs come back for approval."""
    change = decide(name, ["Requested"])
    change.status = "Draft"
    change.response = response
    change.save(ignore_permissions=True)
    close_todos("Pricing Change", change.name)
    assign("Pricing Request", change.pricing_request, [change.owner],
           fmt("Sales allowed your change: edit the costs, then Send Change to Sales. {0}", [text(response)]))
    return {"pricing_request": change.pricing_request, "opportunity": change.opportunity, "side": "Production"}


def send_change_to_sales(name):
    pr = for_production(name, [CHANGE_REQ])
    if not change_is_draft(pr):
        if change_status(pr) == "Requested":
            frappe.throw(_("Sales hasn't allowed the change yet"))
        frappe.throw(_("This change was already sent"))
    check_all_priced(pr)

    change = frappe.get_doc("Pricing Change", pr.pending_change)
    change.set("lines", [])
    for row in cost_changes(pr, json.loads(pr.approved_costs or "[]")):
        change.append("lines", row)
    if not change.lines:
        frappe.throw(_("No cost changed. Use Discard Change instead"))
    change.status = "Pending"
    change.save(ignore_permissions=True)
    assign("Pricing Change", change.name, [opp_owner(pr)],
           fmt("Production changed the costs, review and approve: {0}", [change.reason]))


CHANGE_COLS = [("custom_currency", "Currency"), ("qty", "Qty"), ("rate", "Rate"), ("uom", "UOM"), ("supplier", "Supplier"), ("description", "Description")]


def qty_text(v):
    v = flt(v)
    return str(int(v)) if v == int(v) else str(v)


def cost_text(c, currency):
    return qty_text(c.get("qty")) + " × " + money(c.get("rate"), currency) + " = " + money(flt(c.get("qty")) * flt(c.get("rate")), currency)


def cost_changes(pr, old_rows):
    """What Production changed, for Sales: each cost element added, removed or edited, in its own currency;
    each line's cost and the deal's total cost and minimum selling, in the company currency."""
    base_cur = pr.custom_company_currency or company_currency(frappe.db.get_value("Opportunity", pr.opportunity, "company"))
    cur_of = lambda c: c.get("custom_currency") or pr.currency or base_cur

    def base_of(c):
        if c.get("custom_currency") and c.get("custom_base_amount") not in (None, ""):
            return flt(c.get("custom_base_amount"))
        rate = flt(c.get("custom_exchange_rate")) or rate_to(cur_of(c), base_cur)
        return flt(c.get("qty")) * flt(c.get("rate")) * rate

    out = []
    margins = {}
    for c in frappe.get_doc("Opportunity", pr.opportunity).custom_costing:
        margins[c.requirement] = flt(c.margin)
    old_total = 0.0
    new_total = 0.0
    old_min = 0.0
    new_min = 0.0
    for line in pr.items:
        req = line.requirement
        name = label(line)
        old = [c for c in old_rows if c.get("sales_item_row") == req]
        new = [c for c in pr.costs if c.sales_item_row == req]
        pool = {}
        for c in old:
            pool.setdefault(c.get("item_code"), []).append(c)
        for c in new:
            twins = pool.get(c.item_code) or []
            o = twins.pop(0) if twins else None
            if not o:
                out.append({"line": name, "field": fmt("Added {0}", [c.item_code]), "old_value": "—",
                            "new_value": cost_text(c, cur_of(c))})
                continue
            for f, col in CHANGE_COLS:
                a = o.get(f)
                b = c.get(f)
                if f == "custom_currency":
                    if cur_of(o) == cur_of(c):
                        continue
                    a = cur_of(o)
                    b = cur_of(c)
                elif f in NUMBERS:
                    if abs(flt(a) - flt(b)) < 0.005:
                        continue
                    a = money(a, cur_of(o)) if f == "rate" else qty_text(a)
                    b = money(b, cur_of(c)) if f == "rate" else qty_text(b)
                elif text(a) == text(b):
                    continue
                out.append({"line": name, "field": c.item_code + " · " + _(col),
                            "old_value": text(a) or "—", "new_value": text(b) or "—"})
        for twins in pool.values():
            for o in twins:
                out.append({"line": name, "field": fmt("Removed {0}", [o.get("item_code")]),
                            "old_value": cost_text(o, cur_of(o)), "new_value": "—"})
        was = sum([base_of(c) for c in old])
        now = flt(line.cost)
        m = 1 + margins.get(req, 0) / 100
        old_total += was
        new_total += now
        old_min += was * m
        new_min += now * m
        if abs(was - now) > 0.005:
            out.append({"line": name, "field": _("Line cost"), "old_value": money(was, base_cur), "new_value": money(now, base_cur)})
    if abs(old_total - new_total) > 0.005:
        out.append({"line": _("Deal"), "field": _("Total cost"), "old_value": money(old_total, base_cur),
                    "new_value": money(new_total, base_cur)})
        out.append({"line": _("Deal"), "field": _("Minimum selling"), "old_value": money(old_min, base_cur),
                    "new_value": money(new_min, base_cur)})
    return out


def rebuild_change_lines(name):
    if not has_role("System Manager"):
        frappe.throw(_("Not permitted"))
    change = frappe.get_doc("Pricing Change", name)
    pr = frappe.get_doc("Pricing Request", change.pricing_request)
    change.set("lines", [])
    for row in cost_changes(pr, json.loads(pr.approved_costs or "[]")):
        change.append("lines", row)
    change.save(ignore_permissions=True)
    return len(change.lines)


def discard_cost_change(name):
    pr = for_production(name, [CHANGE_REQ])
    if change_status(pr) not in ["Requested", "Draft"]:
        frappe.throw(_("This change is already with Sales"))
    change = pr.pending_change
    restore_costs(pr)
    frappe.delete_doc("Pricing Change", change, ignore_permissions=True, force=True)


# ---------------------------------------------------------------- Pricing Change decisions

def decide(name, statuses=None):
    change = frappe.get_doc("Pricing Change", name)
    if change.status not in (statuses or ["Pending"]):
        frappe.throw(fmt("This change is already {0}", [_(change.status)]))
    if change.requested_by_side == "Sales":
        if not has_role("Production"):
            frappe.throw(_("Only Production can decide on this change"))
    else:
        get_opp(change.opportunity, "write")
    return change


def close_change(change, status, response):
    change.status = status
    change.response = response
    change.decided_by = frappe.session.user
    change.save(ignore_permissions=True)
    close_todos("Pricing Change", change.name)
    notify(change.owner, "Pricing Change", change.name,
           fmt("Your change {0} was {1}", [change.name, _(status).lower()]))


def approve(name, response):
    change = decide(name)
    pr = frappe.get_doc("Pricing Request", change.pricing_request)
    if change.requested_by_side == "Sales":
        p = json.loads(change.payload or "{}")
        opp = frappe.get_doc("Opportunity", change.opportunity)
        for r in opp.custom_requirements:
            if r.name == p.get("requirement"):
                for f in CHANGE_FIELDS:
                    r.set(f, p.get(f))
        save_opp(opp, {"eye_allow_req_change": True})

        for line in pr.items:
            if line.requirement == p.get("requirement"):
                for f in CHANGE_FIELDS:
                    line.set(f, p.get(f))
        if pr.status == PRICED:
            pr.status = IN_PRICING
        pr.pending_change = None
        pr.flags.eye_system = True
        pr.save(ignore_permissions=True)
        set_opp_status(pr.opportunity, pr.status)
        assign("Pricing Request", pr.name, production_users(),
               fmt("Requirement changed, update the pricing: {0}", [change.reason]), pr.required_by)
    else:
        pr.status = PRICED
        pr.pending_change = None
        pr.approved_costs = None
        pr.flags.eye_system = True
        pr.save(ignore_permissions=True)
        apply_to_opportunity(pr)
    close_change(change, "Approved", response)
    return {"pricing_request": pr.name, "opportunity": change.opportunity, "side": change.requested_by_side}


def reject(name, response):
    need_text(response, "Write why you reject it")
    change = decide(name, ["Pending", "Requested"])  # Sales can refuse before or after the edit
    pr = frappe.get_doc("Pricing Request", change.pricing_request)
    if change.requested_by_side == "Production":
        restore_costs(pr)
    else:
        pr.db_set("pending_change", None)
    close_change(change, "Rejected", response)
    return {"pricing_request": pr.name, "opportunity": change.opportunity, "side": change.requested_by_side}


# ---------------------------------------------------------------- reads for the desk

def get_state(opportunity):
    get_opp(opportunity)
    pending = frappe.get_all("Pricing Change",
                             filters={"opportunity": opportunity, "status": ["in", ["Requested", "Pending"]]},
                             fields=["name", "requested_by_side", "status"])
    return {"locked": locked_requirements(opportunity), "pending": pending}


def pl_view(name):
    """The P&L shown before Deals in Hand, as HTML: selling, cost, profit and margin against the minimum, then each line."""
    opp = get_opp(name)
    cur = opp.currency
    conv = flt(opp.conversion_rate) or 1
    esc = frappe.utils.escape_html
    num = lambda v: frappe.utils.fmt_money(flt(v), precision=0)
    pct = lambda v: str(round(flt(v), 1)) + "%"
    selling = items_total(opp)
    cost = flt(opp.custom_total_cost)
    minimum = flt(opp.custom_total_selling)
    profit = selling - cost
    margin = profit / selling * 100 if selling else 0
    markup = profit / cost * 100 if cost else 0
    gap = selling - minimum
    ok = gap >= -0.005

    reqs = {}
    for r in opp.custom_requirements:
        reqs[r.name] = r
    parts = {}
    n_el = 0
    curs = set()
    for c in opp.custom_costing:
        if c.pricing_request:
            rows = frappe.get_all("Pricing Request Cost", filters={"parent": c.pricing_request, "sales_item_row": c.requirement},
                                  fields=["item_code", "qty", "amount", "custom_currency", "custom_base_amount", "supplier"], order_by="idx")
            parts[c.requirement] = rows
            n_el = n_el + len(rows)
            for e in rows:
                curs.add(e.custom_currency or cur)

    tick = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7"/></svg>'
    warn = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" aria-hidden="true"><path d="M12 8v5M12 17h.01"/><path d="M10.3 3.9L2 18a2 2 0 0 0 1.7 3h16.6a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/></svg>'
    if abs(gap) < 0.5:
        badge = '<span class="eye-pl3-badge ok">' + tick + _("At the minimum") + "</span>"
    elif ok:
        badge = '<span class="eye-pl3-badge ok">' + tick + fmt("Above minimum by {0}", [money(gap, cur)]) + "</span>"
    else:
        badge = '<span class="eye-pl3-badge bad">' + warn + fmt("Below minimum by {0}", [money(-gap, cur)]) + "</span>"
    sub = " · ".join([esc(x) for x in [opp.get("custom_deal_name"), opp.name] if x])
    head = ('<div class="eye-pl3-head"><div><div class="cn">' + esc(opp.customer_name or opp.party_name or opp.name) + "</div>"
            + '<div class="s">' + sub + "</div></div>" + badge + "</div>")

    tone = "pos" if profit > 0.005 else ("neg" if profit < -0.005 else "")
    ring_c = "var(--green-600, #15803d)" if margin >= 0 else "var(--red-500, #e03636)"
    deg = str(round(max(min(abs(margin), 100), 0), 2))
    tiles = (
        '<div class="eye-pl3-tile dark"><div class="l">' + _("Selling") + '</div><div class="v">' + esc(cur) + " " + num(selling) + "</div>"
        + '<div class="s">' + fmt("Minimum {0} · {1} lines", [num(minimum), len(opp.custom_costing)]) + "</div></div>"
        + '<div class="eye-pl3-tile"><div class="l">' + _("Cost") + '</div><div class="v cost">' + num(cost) + "</div>"
        + '<div class="s">' + (fmt("from {0} cost elements · {1} currencies", [n_el, len(curs)]) if n_el else esc(cur)) + "</div></div>"
        + '<div class="eye-pl3-tile"><div class="l">' + _("Gross profit") + '</div><div class="v ' + tone + '">' + num(profit) + "</div>"
        + '<div class="s">' + esc(cur) + "</div></div>"
        + '<div class="eye-pl3-tile ring"><div class="r" style="background:conic-gradient(' + ring_c + " 0 " + deg + "%, var(--subtle-fg, #eef0f3) " + deg + '% 100%)">'
        + "<span>" + str(int(round(margin))) + "%</span></div><div><div class=\"l\">" + _("Margin") + '</div><div class="v sm ' + tone + '">' + pct(margin) + "</div>"
        + '<div class="s">' + fmt("{0} on cost", [pct(markup)]) + "</div></div></div>"
    )

    cw = max(min(cost / selling * 100, 100), 0) if selling else 100
    mark = ""
    if minimum > 0 and selling > 0:
        mp = max(min(minimum / selling * 100, 100), 0)
        mark = ('<div class="eye-pl3-min" style="left:' + str(round(mp, 2)) + '%"><i></i><span>' + _("Minimum") + "</span></div>")
    bar = ('<div class="eye-pl3-bar"><div class="track"><b class="c" style="width:' + str(round(cw, 2)) + '%"></b>'
           + '<b class="p" style="width:' + str(round(100 - cw, 2)) + '%"></b></div>' + mark + "</div>"
           + '<div class="eye-pl3-legend"><span><i class="c"></i>' + _("Cost") + " " + pct(cw) + "</span>"
           + '<span><i class="p"></i>' + _("Profit") + " " + pct(100 - cw) + "</span></div>")

    head_row = ('<div class="eye-pl3-row h"><span>' + _("Line") + '</span><span class="r">' + _("Selling") + '</span><span class="r">'
                + _("Cost") + '</span><span class="r">' + _("Profit") + '</span><span class="r">' + _("Margin") + "</span></div>")
    rows_html = ""
    t_sell = 0.0
    t_cost = 0.0
    for c in opp.custom_costing:
        s = flt(c.selling)
        k = flt(c.cost)
        p = s - k
        t_sell = t_sell + s
        t_cost = t_cost + k
        r = reqs.get(c.requirement)
        item = (r.get("item_code") if r else None) or ""
        desc = text(frappe.utils.strip_html(c.description or ""))
        is_service = item and frappe.db.get_value("Item", item, "item_group") == "Service"
        chip = ('<span class="eye-pl3-chip svc">' + _("Service") + "</span>") if is_service else ('<span class="eye-pl3-chip pt">' + _("Pass-through") + "</span>")
        info = " · ".join([x for x in [esc(desc) if desc and desc != item else "", "qty " + qty_text(c.qty), esc(c.pricing_request or "")] if x])
        m = p / s * 100 if s else 0
        cls = "pos" if p > 0.005 else ("neg" if p < -0.005 else "")
        rows_html += ('<div class="eye-pl3-line"><div class="eye-pl3-row">'
                      + '<div class="n"><div><b>' + esc(item or desc) + "</b>" + chip + '</div><div class="i">' + info + "</div></div>"
                      + '<span class="r strong">' + num(s) + '</span><span class="r cost">' + num(k) + '</span><span class="r ' + cls + '">' + num(p) + "</span>"
                      + '<span class="r mg"><i><b style="width:' + str(round(max(min(m, 100), 0), 1)) + '%"></b></i>' + (pct(m) if s else "—") + "</span></div>")
        els = parts.get(c.requirement) or []
        if els:
            rows_html += '<div class="eye-pl3-els">'
            for e in els:
                what = esc(e.item_code or "")
                if flt(e.qty) != 1:
                    what += ' <span class="q">× ' + qty_text(e.qty) + "</span>"
                if e.supplier:
                    what += ' <span class="q">· ' + esc(e.supplier) + "</span>"
                ecur = e.custom_currency or cur
                conv_txt = money(e.amount, ecur)
                if ecur != cur:
                    conv_txt += ' <span class="q">→</span> ' + esc(cur) + " " + num(flt(e.custom_base_amount) / conv)
                rows_html += '<div class="el"><span>' + what + '</span><span class="r">' + conv_txt + "</span></div>"
            rows_html += "</div>"
        rows_html += "</div>"
    t_p = t_sell - t_cost
    foot = ('<div class="eye-pl3-row t"><span>' + _("Total") + '</span><span class="r">' + num(t_sell) + '</span><span class="r cost">' + num(t_cost)
            + '</span><span class="r ' + ("pos" if t_p > 0.005 else ("neg" if t_p < -0.005 else "")) + '">' + num(t_p)
            + '</span><span class="r">' + (pct(t_p / t_sell * 100) if t_sell else "—") + "</span></div>")
    note = '<div class="eye-pl3-note">' + _("Confirming moves the deal to <b>Deals in Hand</b> with these prices.") + "</div>"
    return {
        "ok": ok,
        "name": opp.name,
        "html": PL_CSS + '<div class="eye-pl3">' + head + '<div class="eye-pl3-tiles">' + tiles + "</div>" + bar
        + head_row + rows_html + foot + note + "</div>",
    }


