def get_pricing(name):
    """Everything the Kanban card dialogs show."""
    opp = get_opp(name)
    locked = set(locked_requirements(name))
    return {
        "status": opp.custom_pricing_status,
        "open": opp.custom_pricing_status in OPEN,
        "required_by": opp.custom_pricing_required_by,
        "notes": opp.custom_pricing_notes,
        "default_margin": opp.custom_default_margin,
        "currency": opp.currency,
        "requirements": [{"name": r.name, "item_code": r.get("item_code"), "description": r.description, "qty": r.qty, "notes": r.notes,
                          "locked": r.name in locked} for r in opp.custom_requirements],
        "costing": [{"name": c.name, "description": c.description, "qty": c.qty, "cost": c.cost,
                     "margin": c.margin, "selling": c.selling} for c in opp.custom_costing],
        "minimum": flt(opp.custom_total_selling),
        "items_total": items_total(opp),
    }


def save_requirements(name, rows, required_by, notes, send):
    """The card's Requirements dialog: update the lines, then maybe send them to Production."""
    opp = get_opp(name, "write")
    current = {}
    for r in opp.custom_requirements:
        current[r.name] = r
    keep = []
    for row in parse(rows) or []:
        if not text(row.get("description")):
            continue
        values = {"description": row.get("description"), "qty": flt(row.get("qty")) or 1, "notes": row.get("notes"),
                  "item_code": row.get("item_code") or None}
        r = current.get(row.get("name"))
        if r:
            r.update(values)
            keep.append(r)
        else:
            keep.append(opp.append("custom_requirements", values))
    opp.set("custom_requirements", keep)
    if required_by:
        opp.custom_pricing_required_by = required_by
    if notes is not None:
        opp.custom_pricing_notes = notes
    opp.save()
    if cint(send):
        return send_to_production(name)


def save_margins(name, margins, default_margin):
    """The card's Margin dialog."""
    opp = get_opp(name, "write")
    margins = parse(margins) or {}
    for c in opp.custom_costing:
        if c.name in margins:
            c.margin = flt(margins[c.name])
    if default_margin not in (None, ""):
        opp.custom_default_margin = flt(default_margin)
    opp.save()
    return {"minimum": flt(opp.custom_total_selling)}


