DOC_OPS = {
    "opp_before_validate": opp_before_validate,
    "opp_validate": opp_validate,
    "opp_on_update": opp_on_update,
    "pr_validate": pr_validate,
    "pr_after_insert": pr_after_insert,
    "pr_on_update": pr_on_update,
    "pr_on_trash": pr_on_trash,
    "q_validate": q_validate,
    "q_on_update": q_on_update,
}


def run(op, f):
    if op == "send_to_production":
        return send_to_production(f.opportunity)
    if op == "reply_to_production":
        return reply_to_production(f.name, f.reply)
    if op == "request_requirement_change":
        return request_requirement_change(f.opportunity, f.requirement, f.reason, f.description, f.qty, f.notes)
    if op == "send_to_sales":
        return send_to_sales(f.name)
    if op == "return_to_sales":
        return return_to_sales(f.name, f.question)
    if op == "request_cost_change":
        return request_cost_change(f.name, f.reason)
    if op == "send_change_to_sales":
        return send_change_to_sales(f.name)
    if op == "discard_cost_change":
        return discard_cost_change(f.name)
    if op == "allow_change":
        return allow_change(f.name, f.response)
    if op == "approve":
        return approve(f.name, f.response)
    if op == "reject":
        return reject(f.name, f.response)
    if op == "get_state":
        return get_state(f.opportunity)
    if op == "breakdown":
        return cost_breakdown(get_opp(f.opportunity))
    if op == "pl_view":
        return pl_view(f.name)
    if op == "stage_check":
        return stage_check(f.name, f.to)
    if op == "flow_steps":
        return flow_steps(f.name)
    if op == "approve_project":
        return approve_project(f.name, f.note)
    if op == "reject_project":
        return reject_project(f.name, f.reason)
    if op == "make_sales_order":
        return retry_sales_order(f.name)
    if op == "rebuild_change_lines":
        return rebuild_change_lines(f.name)
    if op == "get_pricing":
        return get_pricing(f.name)
    if op == "save_requirements":
        return save_requirements(f.name, f.rows, f.required_by, f.notes, f.send)
    if op == "save_margins":
        return save_margins(f.name, f.margins, f.default_margin)
    frappe.throw(fmt("Unknown pricing action: {0}", [op]))


op = form.get("op")
if op in DOC_OPS:
    target = form.get("doc")
    if target is None or isinstance(target, (str, bytes, dict, list)):
        frappe.throw(_("Not permitted"))
    DOC_OPS[op](target)
else:
    frappe.flags.result = run(op, form)
